            kwargs['update_fields'] = {'last_modified'}.union(kwargs['update_fields'])
        if not self.code:
            self.assign_code()
            if 'update_fields' in kwargs:
                kwargs['update_fields'] = {'code'}.union(kwargs['update_fields'])
        if not self.datetime:
