class ProductDetailView(DetailView):
    def get(self, request, *args, **kwargs):
        product = self.object = self.get_object()
        if product.mode == ProductMode.VARIATION_CHILD:
            parent_url = reverse(
                "shuup:product", kwargs=dict(pk=product.variation_parent.pk, slug=product.variation_parent.slug)
            )
            return HttpResponseRedirect("{}?variation={}".format(parent_url, product.sku))
        try:
            shop_product = self.shop_product = product.get_shop_instance(request.shop, allow_cache=True)
        except ShopProduct.DoesNotExist:
            raise Problem(_(u"Error! This product is not available in this shop."))
        errors = list(shop_product.get_visibility_errors(customer=request.customer))
        if errors:
            raise Problem("\n".join(extract_messages(errors)))
        return super(ProductDetailView, self).get(request, *args, **kwargs)
class GDPRFieldProvider(FormFieldProvider):
    def get_fields(self, **kwargs):
        request = kwargs.get("request", None)
        gdpr_settings = get_gdpr_settings(request)
        if not gdpr_settings:
            return []
        user_consent = None
        if is_authenticated(request.user):
            user_consent = GDPRUserConsent.get_for_user(request.user, request.shop)
        fields = []
        for page in get_active_consent_pages(request.shop):
            if user_consent and not user_consent.should_reconsent_to_page(page):
                continue
            key = "accept_{}".format(page.id)
            field = forms.BooleanField(
                label=mark_safe(
                    ugettext(
                        "I have read and accept the <a href='{}' target='_blank' class='gdpr_consent_doc_check'>{}</a>"
                    ).format(reverse("shuup:cms_page", kwargs=dict(url=page.url)), page.title)
                ),
                required=True,
                error_messages=dict(required=self.error_message),
            )
            definition = FormFieldDefinition(name=key, field=field)
            fields.append(definition)
        return fields
def handle_set_customer(request, basket, customer, orderer=None):
    if isinstance(customer, AnonymousContact):
        basket.orderer = AnonymousContact()
    else:
        if not customer.is_active:
            raise ValidationError(_("Customer is not active."), code="invalid_customer")
        if customer.pk:
            customer_shops = customer.shops.all()
            if customer_shops and basket.shop not in customer_shops:
                raise ValidationError(
                    _("Shop does not have all the necessary permissions for this customer."),
                    code="invalid_customer_shop",
                )
        if is_authenticated(request.user):
            request_contact = PersonContact.objects.filter(user=request.user).first() or AnonymousContact()
        else:
            request_contact = AnonymousContact()
        is_superuser = getattr(request.user, "is_superuser", False)
        is_staff = getattr(request.user, "is_staff", False) and request.user in basket.shop.staff_members.all()
        if isinstance(customer, PersonContact):
            if customer != request_contact and is_authenticated(request.user):
                if not (is_superuser or is_staff):
                    raise ValidationError(
                        _("You don't have the required permission to assign this customer."), code="no_permission"
                    )
            basket.orderer = customer
        elif isinstance(customer, CompanyContact):
            if not orderer:
                raise ValidationError(
                    _("You must specify the order, in which customer is a company."), code="invalid_orderer"
                )
            valid_customer = customer and customer.pk
            if not valid_customer:
                raise ValidationError(_("Invalid customer."), code="invalid_customer")
            company_members = customer.members.all()
            if orderer not in company_members:
                raise ValidationError(_("Orderer is not a member of the company."), code="orderer_not_company_member")
            elif not (is_superuser or is_staff) and request_contact not in company_members:
                raise ValidationError(_("You are not a member of the company."), code="not_company_member")
            basket.orderer = orderer
    basket.customer = customer
    return {"ok": True}
def could_edit(request):
    """
    Return true if the context of the given request would allow Xtheme editing.
