        identifier = DEFAULT_IDENTIFIER
    else:
        identifier = "%s-%d-%r-%r" % (name, shop.pk, price, waive_at)
    service = service_model.objects.filter(identifier=identifier).first()
    if not service:
        provider = _get_service_provider(provider_model)
