    Args:
        data (bytes): The data to encrypt.
        outfile (str): The file the encrypted data will be written to.
        passphrase (str): The encryption passphrase.
        count (int): The round count used when deriving a key from the
            passphrase.
    Raises:
        FileNotFoundError if the path to the file did not exist.
    """
    encrypted_data = encrypt(data, passphrase, count=count)
    with atomic_write(outfile) as f:
        f.write(HEADER)
        f.write("\n")
        f.write(encrypted_data)
        f.write("\n")
        f.write(FOOTER)
def decrypt_and_read(infile: str, passphrase: str) -> bytes:
    """Decrypt keys data from file.
    Args:
        infile (str): The file the encrypted data will be written to.
        passphrase (str): The encryption passphrase.
    Returns:
        The decrypted data, as bytes.
    Raises:
        ValueError if something went wrong during decryption.
        FileNotFoundError if the file was not found.
    """
    with open(infile, "r") as f:
        encrypted_data = f.read()
    encrypted_data = encrypted_data.replace("\n", "")
    if not encrypted_data.startswith(HEADER) or not encrypted_data.endswith(FOOTER):
        raise ValueError("Wrong file format.")
    return decrypt(encrypted_data[len(HEADER) : -len(FOOTER)], passphrase)
def encrypt(data: bytes, passphrase: str, count: int = 100000):
    salt = Random.new().read(16)
    derived_key = PBKDF2(passphrase, salt, 64, count, prf)
    aes_key = derived_key[:32]
    hmac_key = derived_key[32:64]
    iv = int.from_bytes(Random.new().read(16), byteorder="big")
    iv &= ~(1 << 63)
    ctr = Counter.new(128, initial_value=iv)
    cipher = AES.new(aes_key, AES.MODE_CTR, counter=ctr)
    encrypted_data = cipher.encrypt(data)
    payload = b"".join(
        (
            bytes([1]),
            salt,
            int.to_bytes(iv, length=16, byteorder="big"),
            int.to_bytes(count, length=4, byteorder="big"),
            encrypted_data,
        )
    )
    hmac = HMAC.new(hmac_key, payload, SHA256).digest()
    return encode_base64(payload + hmac)
class Client:
    def load_store(self):
        """Load the session store and olm account.
        If the SqliteMemoryStore is set as the store a store path isn't
        required, if no store path is provided and a store class that requires
        a path is used this method will be a no op.
        This method does nothing if the store is already loaded.
        Raises LocalProtocolError if a store class, user_id and device_id are
            not set.
        """
        if self.store:
            return
        if not self.user_id:
            raise LocalProtocolError("User id is not set")
        if not self.device_id:
            raise LocalProtocolError("Device id is not set")
        if not self.config.store:
            raise LocalProtocolError("No store class was provided in the config.")
        if self.config.encryption_enabled:
            if self.config.store is SqliteMemoryStore:
                self.store = self.config.store(
                    self.user_id,
                    self.device_id,
                    self.config.pickle_key,
                )
            else:
                if not self.store_path:
                    return
                self.store = self.config.store(
                    self.user_id,
                    self.device_id,
                    self.store_path,
                    self.config.pickle_key,
                    self.config.store_name,
                )
            assert self.store
            self.olm = Olm(self.user_id, self.device_id, self.store)
            self.encrypted_rooms = self.store.load_encrypted_rooms()
            if self.config.store_sync_tokens:
                self.loaded_sync_token = self.store.load_sync_token()
    @store_loaded
    def encrypt(
        self, room_id: str, message_type: str, content: Dict[Any, Any]
    ) -> Tuple[str, Dict[str, str]]:
        """Encrypt a message to be sent to the provided room.
        Args:
            room_id (str): The room id of the room where the message will be
                sent.
            message_type (str): The type of the message.
            content (str): The dictionary containing the content of the
                message.
        Raises `GroupEncryptionError` if the group session for the provided
        room isn't shared yet.
        Raises `MembersSyncError` if the room is encrypted but the room members
        aren't fully loaded due to member lazy loading.
        Returns a tuple containing the new message type and the new encrypted
        content.
        """
        assert self.olm
        try:
            room = self.rooms[room_id]
        except KeyError:
            raise LocalProtocolError(f"No such room with id {room_id} found.")
        if not room.encrypted:
            raise LocalProtocolError(f"Room {room_id} is not encrypted")
        if not room.members_synced:
            raise MembersSyncError(
                "The room is encrypted and the members " "aren't fully synced."
            )
        encrypted_content = self.olm.group_encrypt(
            room_id,
            {"content": content, "type": message_type},
        )
        if "m.relates_to" in content:
            encrypted_content["m.relates_to"] = content["m.relates_to"]
        message_type = "m.room.encrypted"
        return message_type, encrypted_content

class Olm:
    def _olm_encrypt(self, session, recipient_device, message_type, content):
        payload = {
            "sender": self.user_id,
            "sender_device": self.device_id,
            "keys": {"ed25519": self.account.identity_keys["ed25519"]},
            "recipient": recipient_device.user_id,
            "recipient_keys": {
                "ed25519": recipient_device.ed25519,
            },
            "type": message_type,
            "content": content,
        }
        olm_message = session.encrypt(Api.to_json(payload))
        self.store.save_session(recipient_device.curve25519, session)
        return {
            "algorithm": self._olm_algorithm,
            "sender_key": self.account.identity_keys["curve25519"],
            "ciphertext": {
                recipient_device.curve25519: {
                    "type": olm_message.message_type,
                    "body": olm_message.ciphertext,
                }
            },
        }
    def share_with_ourselves(self, event):
        """Share a room key with some other device owned by our own user.
        Args:
            event (RoomKeyRequest): The event of the key request.
        If the key share request is valid this will queue up a to-device
        message that holds the room key.
        Raises EncryptionError if no Olm session was found to encrypt
        the key. Raises OlmTrustError if the device that requested the key is
        not verified. Raises a KeyShareError if the request is invalid and
        can't be handled.
        """
        logger.debug(
            f"Trying to share key {event.session_id} with {event.sender}:{event.requesting_device_id}"
        )
        group_session = self.inbound_group_store.get(
            event.room_id, event.sender_key, event.session_id
        )
        if not group_session:
            raise KeyShareError(
                f"Failed to re-share key {event.session_id} with {event.sender}: No session found"
            )
        try:
            device = self.device_store[event.sender][event.requesting_device_id]
        except KeyError:
            raise KeyShareError(
                f"Failed to re-share key {event.session_id} with {event.sender}: "
                f"Unknown requesting device {event.requesting_device_id}."
            )
        session = self.session_store.get(device.curve25519)
        if not session:
            if device not in self.key_request_devices_no_session:
                self.key_request_devices_no_session.append(device)
            self.key_requests_waiting_for_session[(device.user_id, device.device_id)][
                event.request_id
            ] = event
            raise EncryptionError(
                f"No Olm session found for {device.user_id} and device {device.id}"
            )
        if not device.verified:
            raise OlmUnverifiedDeviceError(
                device,
                f"Failed to re-share key {event.session_id} with {event.sender}: "
                f"Device {event.requesting_device_id} is not verified",
            )
        logger.debug(
            f"Successfully shared a key {event.session_id} with {event.sender}:{event.requesting_device_id}"
        )
        self.outgoing_to_device_messages.append(
            self._encrypt_forwarding_key(event.room_id, group_session, session, device)
        )
    def _create_inbound_session(
        self,
        sender,
        sender_key,
        message,
    ):
        logger.info(f"Creating Inbound session for {sender}")
        session = InboundSession(self.account, message, sender_key)
        logger.info(f"Created Inbound session for {sender}")
        self.account.remove_one_time_keys(session)
        self.save_account()
        return session
    def create_group_session(
        self, sender_key, sender_fp_key, room_id, session_id, session_key
    ):
        logger.info(f"Creating inbound group session for {room_id} from {sender_key}")
        try:
            session = InboundGroupSession(
                session_key, sender_fp_key, sender_key, room_id
            )
            if session.id != session_id:
                raise OlmSessionError(
                    "Mismatched session id while creating " "inbound group session"
                )
        except OlmSessionError as e:
            logger.warn(e)
            return
        self.inbound_group_store.add(session)
        self.save_inbound_group_session(session)
    def create_outbound_group_session(self, room_id):
        logger.info(f"Creating outbound group session for {room_id}")
        session = OutboundGroupSession()
        self.outbound_group_sessions[room_id] = session
        id_key = self.account.identity_keys["curve25519"]
        fp_key = self.account.identity_keys["ed25519"]
        self.create_group_session(
            id_key, fp_key, room_id, session.id, session.session_key
        )
        logger.info(f"Created outbound group session for {room_id}")
    def _try_decrypt(
        self,
        sender,
        sender_key,
        message,
    ):
        plaintext = None
        for session in self.session_store[sender_key]:
            matches = False
            try:
                if isinstance(message, OlmPreKeyMessage):
                    matches = session.matches(message)
                    if not matches:
                        continue
                logger.info(
                    "Trying to decrypt olm message using existing "
                    f"session for {sender} and sender_key {sender_key}"
                )
                plaintext = session.decrypt(message)
                self.save_session(sender_key, session)
                logger.info(
                    "Successfully decrypted olm message " "using existing session"
                )
                return plaintext
            except OlmSessionError as e:
                if matches:
                    logger.error(
                        "Found matching session yet decryption "
                        f"failed for sender {sender} and "
                        f"sender key {sender_key}"
                    )
                    raise EncryptionError("Decryption failed for matching session")
                logger.info(
                    f"Error decrypting olm message from {sender} "
                    f"and sender key {sender_key}: {e}"
                )
        return None
    def _verify_olm_payload(self, sender, payload):
        if sender != payload["sender"]:
            raise VerificationError("Mismatched sender in Olm payload")
        if self.user_id != payload["recipient"]:
            raise VerificationError("Mismatched recipient in Olm " "payload")
        if (
            self.account.identity_keys["ed25519"]
            != payload["recipient_keys"]["ed25519"]
        ):
            raise VerificationError("Mismatched recipient key in " "Olm payload")
        return True
    def _handle_room_key_event(
        self,
        sender,
        sender_key,
        payload,
    ):
        event = RoomKeyEvent.from_dict(payload, sender, sender_key)
        if isinstance(event, (BadEvent, UnknownBadEvent)):
            return event
        content = payload["content"]
        if event.algorithm != "m.megolm.v1.aes-sha2":
            logger.error(f"Error: unsupported room key of type {event.algorithm}")
            return event
        logger.info(
            f"Received new group session key for room {event.room_id} from {sender}"
        )
        sender_fp_key = payload["keys"].get("ed25519", None)
        if not sender_fp_key:
            return None
        self.create_group_session(
            sender_key,
            sender_fp_key,
            content["room_id"],
            content["session_id"],
            content["session_key"],
        )
        return event
    def _should_accept_forward(
        self,
        sender: str,
        sender_key: str,
        event: ForwardedRoomKeyEvent,
    ) -> bool:
        if event.algorithm != "m.megolm.v1.aes-sha2":
            logger.error(
                f"Error: unsupported forwarded room key of type {event.algorithm}"
            )
            return False
        elif event.session_id not in self.outgoing_key_requests:
            logger.info(
                "Ignoring session key we have not requested from device {}.", sender_key
            )
            return False
        key_request = self.outgoing_key_requests[event.session_id]
        if (
            event.algorithm != key_request.algorithm
            or event.room_id != key_request.room_id
            or event.session_id != key_request.session_id
        ):
            logger.info(
                "Ignoring session key with mismatched algorithm, room_id, or "
                "session id."
            )
            return False
        device = self.device_store.device_from_sender_key(event.sender, sender_key)
        if not device or not device.verified or not device.user_id == self.user_id:
            logger.warn(
                "Received a forwarded room key from a untrusted device "
                f"{event.sender}, {sender_key}"
            )
            return False
        return True
    def _handle_forwarded_room_key_event(
        self,
        sender,
        sender_key,
        payload,
    ):
        event = ForwardedRoomKeyEvent.from_dict(payload, sender, sender_key)
        if isinstance(event, (BadEvent, UnknownBadEvent)):
            return event
        if not self._should_accept_forward(sender, sender_key, event):
            return None
        content = payload["content"]
        session_sender_key = content["sender_key"]
        signing_key = content["sender_claimed_ed25519_key"]
        chain = content["forwarding_curve25519_key_chain"]
        chain.append(session_sender_key)
        session = Olm._import_group_session(
            content["session_key"],
            signing_key,
            session_sender_key,
            event.room_id,
            chain,
        )
        if not session:
            return None
        if self.inbound_group_store.add(session):
            self.save_inbound_group_session(session)
        key_request = self.outgoing_key_requests.pop(event.session_id)
        self.store.remove_outgoing_key_request(key_request)
        self.outgoing_to_device_messages.append(
            key_request.as_cancellation(self.user_id, self.device_id)
        )
        return event
    def _handle_olm_event(
        self,
        sender,
        sender_key,
        payload,
    ):
        logger.info(
            f"Received Olm event of type: {payload['type']} from {sender} {sender_key}"
        )
        if payload["type"] == "m.room_key":
            event = self._handle_room_key_event(sender, sender_key, payload)
            return event
        elif payload["type"] == "m.forwarded_room_key":
            return self._handle_forwarded_room_key_event(sender, sender_key, payload)
        elif payload["type"] == "m.dummy":
            return DummyEvent.from_dict(payload, sender, sender_key)
        else:
            logger.warn(f"Received unsupported Olm event of type {payload['type']}")
            return None
    def decrypt_megolm_event(self, event, room_id=None):
        room_id = room_id or event.room_id
        if not room_id:
            raise EncryptionError("Event doesn't contain a room id")
        verified = False
        session = self.inbound_group_store.get(
            room_id, event.sender_key, event.session_id
        )
        if not session:
            message = (
                "Error decrypting megolm event, no session found "
                f"with session id {event.session_id} for room {room_id}"
            )
            self.check_if_wedged(event)
            logger.warn(message)
            raise EncryptionError(message)
        try:
            plaintext, message_index = session.decrypt(event.ciphertext)
        except OlmGroupSessionError as e:
            message = f"Error decrypting megolm event: {str(e)}"
            logger.warn(message)
            raise EncryptionError(message)
        if not self.message_index_ok(message_index, event):
            raise EncryptionError(
                f"Duplicate message index, possible replay attack from "
                f"{event.sender} {event.sender_key} {event.session_id}"
            )
        if (
            event.sender == self.user_id
            and event.device_id == self.device_id
            and session.ed25519 == self.account.identity_keys["ed25519"]
            and event.sender_key == self.account.identity_keys["curve25519"]
        ):
            verified = True
        else:
            try:
                device = self.device_store[event.sender][event.device_id]
            except KeyError:
                self.users_for_key_query.add(event.sender)
            else:
                if self.is_device_verified(device) and not session.forwarding_chain:
                    if (
                        device.ed25519 != session.ed25519
                        or device.curve25519 != event.sender_key
                    ):
                        message = (
                            f"Device keys mismatch in event sent by device {device.id}."
                        )
                        logger.warn(message)
                        raise EncryptionError(message)
                    logger.info(f"Event {event.event_id} successfully verified")
                    verified = True
        try:
            parsed_dict = json.loads(plaintext)
        except JSONDecodeError as e:
            raise EncryptionError(f"Error parsing payload: {str(e)}")
        bad = validate_or_badevent(parsed_dict, Schemas.room_megolm_decrypted)
        if bad:
            return bad
        parsed_dict["event_id"] = event.event_id
        if "m.relates_to" not in parsed_dict["content"]:
            try:
                parsed_dict["content"]["m.relates_to"] = event.source["content"][
                    "m.relates_to"
                ]
            except KeyError:
                pass
        parsed_dict["sender"] = event.sender
        parsed_dict["origin_server_ts"] = event.server_timestamp
        if event.transaction_id:
            parsed_dict["unsigned"] = {"transaction_id": event.transaction_id}
        new_event = Event.parse_decrypted_event(parsed_dict)
        if isinstance(new_event, UnknownBadEvent):
            return new_event
        new_event.decrypted = True
        new_event.verified = verified
        new_event.sender_key = event.sender_key
        new_event.session_id = event.session_id
        new_event.room_id = room_id
        return new_event
    def decrypt(
        self,
        sender,
        sender_key,
        message,
    ):
        try:
            plaintext = self._try_decrypt(sender, sender_key, message)
        except EncryptionError:
            self._mark_device_for_unwedging(sender, sender_key)
            return None
        if plaintext is None:
            if not isinstance(message, OlmPreKeyMessage):
                self._mark_device_for_unwedging(sender, sender_key)
                return None
            try:
                s = self._create_inbound_session(sender, sender_key, message)
                plaintext = s.decrypt(message)
                self.session_store.add(sender_key, s)
                self.save_session(sender_key, s)
            except OlmSessionError as e:
                logger.error(
                    f"Failed to create new session from prekeymessage: {str(e)}"
                )
                self._mark_device_for_unwedging(sender, sender_key)
                return None
        if plaintext is None:
            logger.error("Failed to decrypt Olm message: unknown error")
            return None
        try:
            parsed_payload = json.loads(plaintext)
        except JSONDecodeError as e:
            logger.error(f"Failed to parse Olm message payload: {str(e)}")
            return None
        try:
            validate_json(parsed_payload, Schemas.olm_event)
        except (ValidationError, SchemaError) as e:
            logger.error(
                f"Error validating decrypted Olm event from {sender}: {str(e.message)}"
            )
            return None
        try:
            self._verify_olm_payload(sender, parsed_payload)
        except VerificationError as e:
            logger.error(e)
            return None
        else:
            return self._handle_olm_event(sender, sender_key, parsed_payload)
    def share_group_session_parallel(
        self, room_id: str, users: List[str], ignore_unverified_devices: bool = False
    ) -> Iterator[Tuple[Set[Tuple[str, str]], Dict[str, Any]]]:
        logger.info(f"Sharing group session for room {room_id}")
        if room_id not in self.outbound_group_sessions:
            self.create_outbound_group_session(room_id)
        group_session = self.outbound_group_sessions[room_id]
        if group_session.shared:
            self.create_outbound_group_session(room_id)
            group_session = self.outbound_group_sessions[room_id]
        key_content = {
            "algorithm": self._megolm_algorithm,
            "room_id": room_id,
            "session_id": group_session.id,
            "session_key": group_session.session_key,
        }
        already_shared_set = group_session.users_shared_with
        ignored_set = group_session.users_ignored
        user_map = []
        mark_as_ignored = []
        for user_id in users:
            for device in self.device_store.active_user_devices(user_id):
                if device.id == self.device_id:
                    ignored_set.add((user_id, device.id))
                    continue
                if self.is_device_blacklisted(device):
                    ignored_set.add((user_id, device.id))
                    continue
                if (user_id, device.id) in already_shared_set or (
                    user_id,
                    device.id,
                ) in ignored_set:
                    continue
                session = self.session_store.get(device.curve25519)
                if not session:
                    logger.warn(
                        f"Missing Olm session for user {user_id} and device "
                        f"{device.id}, skipping"
                    )
                    continue
                if not self.is_device_verified(device):
                    if self.is_device_ignored(device):
                        pass
                    elif ignore_unverified_devices:
                        mark_as_ignored.append(device)
                    else:
                        raise OlmUnverifiedDeviceError(
                            device,
                            f"Device {device.id} for user {device.user_id} is not "
                            f"verified or blacklisted.",
                        )
                user_map.append((user_id, device, session))
        if mark_as_ignored:
            self.store.ignore_devices(mark_as_ignored)
        for user_map_chunk in chunks(user_map, self._maxToDeviceMessagesPerRequest):
            to_device_dict = {"messages": {}}
            sharing_with = set()
            for user_id, device, session in user_map_chunk:
                olm_dict = self._olm_encrypt(session, device, "m.room_key", key_content)
                sharing_with.add((user_id, device.id))
                if user_id not in to_device_dict["messages"]:
                    to_device_dict["messages"][user_id] = {}
                to_device_dict["messages"][user_id][device.id] = olm_dict
            yield (sharing_with, to_device_dict)
    def share_group_session(
        self,
        room_id,
        users,
        ignore_missing_sessions=False,
        ignore_unverified_devices=False,
    ):
        logger.info(f"Sharing group session for room {room_id}")
        if room_id not in self.outbound_group_sessions:
            self.create_outbound_group_session(room_id)
        group_session = self.outbound_group_sessions[room_id]
        if group_session.shared:
            raise LocalProtocolError("Group session already shared")
        key_content = {
            "algorithm": self._megolm_algorithm,
            "room_id": room_id,
            "session_id": group_session.id,
            "session_key": group_session.session_key,
        }
        to_device_dict = {"messages": {}}
        already_shared_set = group_session.users_shared_with
        ignored_set = group_session.users_ignored
        user_map = []
        mark_as_ignored = []
        for user_id in users:
            for device in self.device_store.active_user_devices(user_id):
                if device.id == self.device_id:
                    ignored_set.add((user_id, device.id))
                    continue
                if self.is_device_blacklisted(device):
                    ignored_set.add((user_id, device.id))
                    continue
                if (user_id, device.id) in already_shared_set or (
                    user_id,
                    device.id,
                ) in ignored_set:
                    continue
                session = self.session_store.get(device.curve25519)
                if not session:
                    if ignore_missing_sessions:
                        ignored_set.add((user_id, device.id))
                        continue
                    else:
                        raise EncryptionError(
                            f"Missing Olm session for user {user_id} and device {device.id}"
                        )
                if not self.is_device_verified(device):
                    if self.is_device_ignored(device):
                        pass
                    elif ignore_unverified_devices:
                        mark_as_ignored.append(device)
                    else:
                        raise OlmUnverifiedDeviceError(
                            device,
                            f"Device {device.id} for user {device.user_id} is not verified or blacklisted.",
                        )
                user_map.append((user_id, device, session))
                if len(user_map) >= self._maxToDeviceMessagesPerRequest:
                    break
            if len(user_map) >= self._maxToDeviceMessagesPerRequest:
                break
        sharing_with = set()
        if mark_as_ignored:
            self.store.ignore_devices(mark_as_ignored)
        for user_id, device, session in user_map:
            olm_dict = self._olm_encrypt(session, device, "m.room_key", key_content)
            sharing_with.add((user_id, device.id))
            if user_id not in to_device_dict["messages"]:
                to_device_dict["messages"][user_id] = {}
            to_device_dict["messages"][user_id][device.id] = olm_dict
        return sharing_with, to_device_dict
    def save_session(self, curve_key, session):
        self.store.save_session(curve_key, session)
    def save_inbound_group_session(self, session):
        self.store.save_inbound_group_session(session)
    def save_account(self, account=None):
        if account:
            self.store.save_account(account)
        else:
            self.store.save_account(self.account)
        logger.debug("Saving account")
    @staticmethod
    def import_keys_static(infile, passphrase):
        sessions = []
        try:
            data = decrypt_and_read(infile, passphrase)
        except ValueError as e:
            raise EncryptionError(e)
        try:
            session_list = json.loads(data)
        except JSONDecodeError as e:
            raise EncryptionError(f"Error parsing key file: {str(e)}")
        try:
            validate_json(session_list, Schemas.megolm_key_import)
        except (ValidationError, SchemaError) as e:
            logger.warning(e)
            raise EncryptionError(f"Error parsing key file: {str(e)}")
        for session_dict in session_list:
            if session_dict["algorithm"] != Olm._megolm_algorithm:
                logger.warning("Ignoring session with unsupported algorithm.")
                continue
            session = Olm._import_group_session(
                session_dict["session_key"],
                session_dict["sender_claimed_keys"]["ed25519"],
                session_dict["sender_key"],
                session_dict["room_id"],
                session_dict["forwarding_curve25519_key_chain"],
            )
            if not session:
                continue
            sessions.append(session)
        return sessions
    def import_keys(self, infile, passphrase):
        """Import Megolm decryption keys.
        The keys will be added to the current instance as well as written to
        database.
        Args:
            infile (str): The file containing the keys.
            passphrase (str): The decryption passphrase.
        """
        sessions = Olm.import_keys_static(infile, passphrase)
        for session in sessions:
            if self.inbound_group_store.add(session):
                self.save_inbound_group_session(session)
        logger.info(f"Successfully imported encryption keys from {infile}")
def decrypt_attachment(ciphertext: bytes, key: str, hash: str, iv: str):
    """Decrypt an encrypted attachment.
    Args:
        ciphertext (bytes): The data to decrypt.
        key (str): AES_CTR JWK key object.
        hash (str): Base64 encoded SHA-256 hash of the ciphertext.
        iv (str): Base64 encoded 16 byte AES-CTR IV.
    Returns:
        The plaintext bytes.
    Raises:
        EncryptionError if the integrity check fails.
    """
    expected_hash = unpaddedbase64.decode_base64(hash)
    h = SHA256.new()
    h.update(ciphertext)
    if h.digest() != expected_hash:
        raise EncryptionError("Mismatched SHA-256 digest.")
    try:
        byte_key: bytes = unpaddedbase64.decode_base64(key)
    except (BinAsciiError, TypeError):
        raise EncryptionError("Error decoding key.")
    try:
        byte_iv: bytes = unpaddedbase64.decode_base64(iv)
    except (BinAsciiError, TypeError):
        raise EncryptionError("Error decoding initial values.")
    prefix: bytes = byte_iv[:8]
    cnt: int = int.from_bytes(byte_iv[8:], "big")
    ctr = Counter.new(64, prefix=prefix, initial_value=cnt)
    try:
        cipher = AES.new(byte_key, AES.MODE_CTR, counter=ctr)
    except ValueError as e:
        raise EncryptionError(e)
    return cipher.decrypt(ciphertext)
class AsyncClient(Client):
    @logged_in
    @store_loaded
    async def cancel_key_verification(
        self,
        transaction_id: str,
        reject: bool = False,
        tx_id: Optional[str] = None,
    ) -> Union[ToDeviceResponse, ToDeviceError]:
        """Cancel a interactive key verification with the given device.
        Returns either a `ToDeviceResponse` if the request was successful or
        a `ToDeviceError` if there was an error with the request.
        Args:
            transaction_id (str): An transaction id of a valid key verification
                process.
            reject (bool): Is the cancelation reason because we're rejecting
                the short auth string and mark it as mismatching or a normal
                user cancelation.
        Raises a LocalProtocolError no verification process with the given
        transaction ID exists or if reject is True and the short auth string
        couldn't be shown yet because plublic keys weren't yet exchanged.
        """
        if transaction_id not in self.key_verifications:
            raise LocalProtocolError(
                f"Key verification with the transaction id {transaction_id} does not exist."
            )
        sas = self.key_verifications[transaction_id]
        if reject:
            sas.reject_sas()
        else:
            sas.cancel()
        message = sas.get_cancellation()
        return await self.to_device(message, tx_id)
    @logged_in
    async def room_send(
        self,
        room_id: str,
        message_type: str,
        content: Dict[Any, Any],
        tx_id: Optional[str] = None,
        ignore_unverified_devices: bool = False,
    ):
        """Send a message to a room.
        Calls receive_response() to update the client state if necessary.
        Args:
            room_id(str): The room id of the room where the message should be
                sent to.
            message_type(str): A string identifying the type of the message.
            content(Dict[Any, Any]): A dictionary containing the content of the
                message.
            tx_id(str, optional): The transaction ID of this event used to
                uniquely identify this message.
            ignore_unverified_devices(bool): If the room is encrypted and
                contains unverified devices, the devices can be marked as
                ignored here. Ignored devices will still receive encryption
                keys for messages but they won't be marked as verified.
        If the room where the message should be sent is encrypted the message
        will be encrypted before sending.
        This method also makes sure that the room members are fully synced and
        that keys are queried before sending messages to an encrypted room.
        If the method can't sync the state fully to send out an encrypted
        message after a couple of retries it raises `SendRetryError`.
        Raises `LocalProtocolError` if the client isn't logged in.
        """
        uuid: Union[str, UUID] = tx_id or uuid4()
        if self.olm:
            try:
                room = self.rooms[room_id]
            except KeyError:
                raise LocalProtocolError(f"No such room with id {room_id} found.")
            if room.encrypted:
                if not room.members_synced:
                    responses = []
                    responses.append(await self.joined_members(room_id))
                    if self.should_query_keys:
                        responses.append(await self.keys_query())
                if self.olm.should_share_group_session(room_id):
                    try:
                        event = self.sharing_session[room_id]
                        await event.wait()
                    except KeyError:
                        await self.share_group_session(
                            room_id,
                            ignore_unverified_devices=ignore_unverified_devices,
                        )
                if message_type != "m.reaction":
                    message_type, content = self.encrypt(room_id, message_type, content)
        method, path, data = Api.room_send(
            self.access_token, room_id, message_type, content, uuid
        )
        return await self._send(RoomSendResponse, method, path, data, (room_id,))
    @logged_in
    @store_loaded
    async def share_group_session(
        self,
        room_id: str,
        ignore_unverified_devices: bool = False,
    ) -> Union[ShareGroupSessionResponse, ShareGroupSessionError]:
        """Share a group session with a room.
        This method sends a group session to members of a room.
        Automatically called by room_send().
        Calls receive_response() to update the client state if necessary.
        Args:
            room_id(str): The room id of the room where the message should be
                sent to.
            ignore_unverified_devices(bool): Mark unverified devices as
                ignored. Ignored devices will still receive encryption
                keys for messages but they won't be marked as verified.
        Raises LocalProtocolError if the client isn't logged in, if the session
        store isn't loaded, no room with the given room id exists, the room
        isn't an encrypted room or a key sharing request is already in flight
        for this room.
        """
        assert self.olm
        try:
            room = self.rooms[room_id]
        except KeyError:
            raise LocalProtocolError(f"No such room with id {room_id}")
        if not room.encrypted:
            raise LocalProtocolError(f"Room with id {room_id} is not encrypted")
        if room_id in self.sharing_session:
            raise LocalProtocolError(f"Already sharing a group session for {room_id}")
        self.sharing_session[room_id] = AsyncioEvent()
        missing_sessions = self.get_missing_sessions(room_id)
        if missing_sessions:
            await self.keys_claim(missing_sessions)
        shared_with = set()
        try:
            requests = []
            for sharing_with, to_device_dict in self.olm.share_group_session_parallel(
                room_id,
                list(room.users.keys()),
                ignore_unverified_devices=ignore_unverified_devices,
            ):
                method, path, data = Api.to_device(
                    self.access_token, "m.room.encrypted", to_device_dict, uuid4()
                )
                requests.append(
                    self._send(
                        ShareGroupSessionResponse,
                        method,
                        path,
                        data,
                        response_data=(room_id, sharing_with),
                    )
                )
            for response in await asyncio.gather(*requests, return_exceptions=True):
                if isinstance(response, ShareGroupSessionResponse):
                    shared_with.update(response.users_shared_with)
            self.olm.outbound_group_sessions[room_id].shared = True
        except ClientConnectionError:
            raise
        finally:
            event = self.sharing_session.pop(room_id)
            event.set()
        return ShareGroupSessionResponse(room_id, shared_with)
    @logged_in
    @store_loaded
    async def request_room_key(
        self,
        event: MegolmEvent,
        tx_id: Optional[str] = None,
    ) -> Union[RoomKeyRequestResponse, RoomKeyRequestError]:
        """Request a missing room key.
        This sends out a message to other devices requesting a room key from
        them.
        Calls receive_response() to update the client state if necessary.
        Returns either a `RoomKeyRequestResponse` if the request was successful
        or a `RoomKeyRequestError` if there was an error with the request.
        Raises a LocalProtocolError if the room key was already requested.
        Args:
            event (MegolmEvent): An undecrypted MegolmEvent for which we would
                like to request the decryption key.
        """
        uuid = tx_id or uuid4()
        if event.session_id in self.outgoing_key_requests:
            raise LocalProtocolError(
                "A key sharing request is already sent" " out for this session id."
            )
        assert self.user_id
        assert self.device_id
        message = event.as_key_request(self.user_id, self.device_id)
        method, path, data = Api.to_device(
            self.access_token, message.type, message.as_dict(), uuid
        )
        return await self._send(
            RoomKeyRequestResponse,
            method,
            path,
            data,
            (
                event.session_id,
                event.session_id,
                event.room_id,
                event.algorithm,
            ),
        )
def validate_json(instance, schema):
    Validator(schema, format_checker=FormatChecker()).validate(instance)
def verify(schema, error_class, pass_arguments=True):
    def decorator(f):
        @wraps(f)
        def wrapper(cls, parsed_dict, *args, **kwargs):
            try:
                logger.info("Validating response schema")
                validate_json(parsed_dict, schema)
            except (SchemaError, ValidationError) as e:
                logger.warn("Error validating response: " + str(e.message))
                if pass_arguments:
                    return error_class.from_dict(parsed_dict, *args, **kwargs)
                else:
                    return error_class.from_dict(parsed_dict)
            return f(cls, parsed_dict, *args, **kwargs)
