        self.inline.links = {}
        self.inline.footnotes = {}
        if not self.footnotes:
            return out
        footnotes = filter(lambda o: keys.get(o['key']), self.footnotes)
        self.footnotes = sorted(
            footnotes, key=lambda o: keys.get(o['key']), reverse=True
        )
