        """Rendering paragraph tags. Like ``<p>``."""
        return '<p>%s</p>\n' % text.strip(' ')
    def text(self, text):
        """Rendering unformatted text.
        :param text: text content.
        """
        if self.options.get('parse_block_html'):
            return text
        return escape(text)
    def escape(self, text):
        """Rendering escape sequence.
        :param text: text content.
        """
        return escape(text)
