class EventCreationHandler:
    async def persist_and_notify_client_event(
        self,
        requester: Requester,
        event: EventBase,
        context: EventContext,
        ratelimit: bool = True,
        extra_users: Optional[List[UserID]] = None,
    ) -> EventBase:
        """Called when we have fully built the event, have already
        calculated the push actions for the event, and checked auth.
        This should only be run on the instance in charge of persisting events.
        Returns:
            The persisted event. This may be different than the given event if
            it was de-duplicated (e.g. because we had already persisted an
            event with the same transaction ID.)
        """
        extra_users = extra_users or []
        assert self.storage.persistence is not None
        assert self._events_shard_config.should_handle(
            self._instance_name, event.room_id
        )
        if ratelimit:
            is_admin_redaction = False
            if event.type == EventTypes.Redaction:
                assert event.redacts is not None
                original_event = await self.store.get_event(
                    event.redacts,
                    redact_behaviour=EventRedactBehaviour.AS_IS,
                    get_prev_content=False,
                    allow_rejected=False,
                    allow_none=True,
                )
                is_admin_redaction = bool(
                    original_event and event.sender != original_event.sender
                )
            await self.request_ratelimiter.ratelimit(
                requester, is_admin_redaction=is_admin_redaction
            )
        await self._maybe_kick_guest_users(event, context)
        if event.type == EventTypes.CanonicalAlias:
            original_alias = None
            original_alt_aliases: List[str] = []
            original_event_id = event.unsigned.get("replaces_state")
            if original_event_id:
                original_event = await self.store.get_event(original_event_id)
                if original_event:
                    original_alias = original_event.content.get("alias", None)
                    original_alt_aliases = original_event.content.get("alt_aliases", [])
            room_alias_str = event.content.get("alias", None)
            directory_handler = self.hs.get_directory_handler()
            if room_alias_str and room_alias_str != original_alias:
                await self._validate_canonical_alias(
                    directory_handler, room_alias_str, event.room_id
                )
            alt_aliases = event.content.get("alt_aliases", [])
            if not isinstance(alt_aliases, (list, tuple)):
                raise SynapseError(
                    400, "The alt_aliases property must be a list.", Codes.INVALID_PARAM
                )
            if not isinstance(original_alt_aliases, (list, tuple)):
                original_alt_aliases = []
            new_alt_aliases = set(alt_aliases) - set(original_alt_aliases)
            if new_alt_aliases:
                for alias_str in new_alt_aliases:
                    await self._validate_canonical_alias(
                        directory_handler, alias_str, event.room_id
                    )
        federation_handler = self.hs.get_federation_handler()
        if event.type == EventTypes.Member:
            if event.content["membership"] == Membership.INVITE:
                event.unsigned[
                    "invite_room_state"
                ] = await self.store.get_stripped_room_state_from_event_context(
                    context,
                    self.room_prejoin_state_types,
                    membership_user_id=event.sender,
                )
                invitee = UserID.from_string(event.state_key)
                if not self.hs.is_mine(invitee):
                    returned_invite = await federation_handler.send_invite(
                        invitee.domain, event
                    )
                    event.unsigned.pop("room_state", None)
                    event.signatures.update(returned_invite.signatures)
            if event.content["membership"] == Membership.KNOCK:
                event.unsigned[
                    "knock_room_state"
                ] = await self.store.get_stripped_room_state_from_event_context(
                    context,
                    self.room_prejoin_state_types,
                )
        if event.type == EventTypes.Redaction:
            assert event.redacts is not None
            original_event = await self.store.get_event(
                event.redacts,
                redact_behaviour=EventRedactBehaviour.AS_IS,
                get_prev_content=False,
                allow_rejected=False,
                allow_none=True,
            )
            room_version = await self.store.get_room_version_id(event.room_id)
            room_version_obj = KNOWN_ROOM_VERSIONS[room_version]
            if original_event:
                if original_event.type == EventTypes.Create:
                    raise AuthError(403, "Redacting create events is not permitted")
                if original_event.room_id != event.room_id:
                    raise SynapseError(400, "Cannot redact event from a different room")
                if original_event.type == EventTypes.ServerACL:
                    raise AuthError(403, "Redacting server ACL events is not permitted")
                is_msc2716_event = (
                    original_event.type == EventTypes.MSC2716_INSERTION
                    or original_event.type == EventTypes.MSC2716_BATCH
                    or original_event.type == EventTypes.MSC2716_MARKER
                )
                if not room_version_obj.msc2716_historical and is_msc2716_event:
                    raise AuthError(
                        403,
                        "Redacting MSC2716 events is not supported in this room version",
                    )
            prev_state_ids = await context.get_prev_state_ids()
            auth_events_ids = self._event_auth_handler.compute_auth_events(
                event, prev_state_ids, for_verification=True
            )
            auth_events_map = await self.store.get_events(auth_events_ids)
            auth_events = {(e.type, e.state_key): e for e in auth_events_map.values()}
            if event_auth.check_redaction(
                room_version_obj, event, auth_events=auth_events
            ):
                if not original_event:
                    raise NotFoundError("Could not find event %s" % (event.redacts,))
                if event.user_id != original_event.user_id:
                    raise AuthError(403, "You don't have permission to redact events")
                event.internal_metadata.recheck_redaction = False
        if event.type == EventTypes.Create:
            prev_state_ids = await context.get_prev_state_ids()
            if prev_state_ids:
                raise AuthError(403, "Changing the room create event is forbidden")
        if event.type == EventTypes.MSC2716_INSERTION:
            room_version = await self.store.get_room_version_id(event.room_id)
            room_version_obj = KNOWN_ROOM_VERSIONS[room_version]
            create_event = await self.store.get_create_event_for_room(event.room_id)
            room_creator = create_event.content.get(EventContentFields.ROOM_CREATOR)
            if room_version_obj.msc2716_historical or (
                self.config.experimental.msc2716_enabled
                and event.sender == room_creator
            ):
                next_batch_id = event.content.get(
                    EventContentFields.MSC2716_NEXT_BATCH_ID
                )
                conflicting_insertion_event_id = None
                if next_batch_id:
                    conflicting_insertion_event_id = (
                        await self.store.get_insertion_event_id_by_batch_id(
                            event.room_id, next_batch_id
                        )
                    )
                if conflicting_insertion_event_id is not None:
                    raise SynapseError(
                        HTTPStatus.BAD_REQUEST,
                        "Another insertion event already exists with the same next_batch_id",
                        errcode=Codes.INVALID_PARAM,
                    )
        backfilled = False
        if event.internal_metadata.is_historical():
            backfilled = True
        (
            event,
            event_pos,
            max_stream_token,
        ) = await self.storage.persistence.persist_event(
            event, context=context, backfilled=backfilled
        )
        if self._ephemeral_events_enabled:
            self._message_handler.maybe_schedule_expiry(event)
        async def _notify() -> None:
            try:
                await self.notifier.on_new_room_event(
                    event, event_pos, max_stream_token, extra_users=extra_users
                )
            except Exception:
                logger.exception(
                    "Error notifying about new room event %s",
                    event.event_id,
                )
        run_in_background(_notify)
        if event.type == EventTypes.Message:
            run_in_background(self._bump_active_time, requester.user)
        return event
class TypingWriterHandler(FollowerTypingHandler):
    async def started_typing(
        self, target_user: UserID, requester: Requester, room_id: str, timeout: int
    ) -> None:
        target_user_id = target_user.to_string()
        auth_user_id = requester.user.to_string()
        if not self.is_mine_id(target_user_id):
            raise SynapseError(400, "User is not hosted on this homeserver")
        if target_user_id != auth_user_id:
            raise AuthError(400, "Cannot set another user's typing state")
        if requester.shadow_banned:
            await self.clock.sleep(random.randint(1, 10))
            raise ShadowBanError()
        await self.auth.check_user_in_room(room_id, target_user_id)
        logger.debug("%s has started typing in %s", target_user_id, room_id)
        member = RoomMember(room_id=room_id, user_id=target_user_id)
        was_present = member.user_id in self._room_typing.get(room_id, set())
        now = self.clock.time_msec()
        self._member_typing_until[member] = now + timeout
        self.wheel_timer.insert(now=now, obj=member, then=now + timeout)
        if was_present:
            return
        self._push_update(member=member, typing=True)
class GroupsServerHandler(GroupsServerWorkerHandler):
    async def remove_user_from_group(
        self, group_id: str, user_id: str, requester_user_id: str, content: JsonDict
    ) -> JsonDict:
        """Remove a user from the group; either a user is leaving or an admin
        kicked them.
        """
        await self.check_group_is_ours(group_id, requester_user_id, and_exists=True)
        is_kick = False
        if requester_user_id != user_id:
            is_admin = await self.store.is_user_admin_in_group(
                group_id, requester_user_id
            )
            if not is_admin:
                raise SynapseError(403, "User is not admin in group")
            is_kick = True
        await self.store.remove_user_from_group(group_id, user_id)
        if is_kick:
            if self.hs.is_mine_id(user_id):
                groups_local = self.hs.get_groups_local_handler()
                assert isinstance(
                    groups_local, GroupsLocalHandler
                ), "Workers cannot remove users from groups."
                await groups_local.user_removed_from_group(group_id, user_id, {})
            else:
                await self.transport_client.remove_user_from_group_notification(
                    get_domain_from_id(user_id), group_id, user_id, {}
                )
        if not self.hs.is_mine_id(user_id):
            await self.store.maybe_delete_remote_profile_cache(user_id)
        users = await self.store.get_users_in_group(group_id, include_private=True)
        if not users:
            await self.store.delete_group(group_id)
        return {}
