@signature(
    ("num_literal", "int128", "uint256", "bytes32", "Bytes", "String", "bool", "decimal"), "*"
)
def to_int256(expr, args, kwargs, context):
    in_arg = args[0]
    input_type, _ = get_type(in_arg)
    if input_type == "num_literal":
        if isinstance(in_arg, int):
            if not SizeLimits.in_bounds("int256", in_arg):
                raise InvalidLiteral(f"Number out of range: {in_arg}")
            return LLLnode.from_list(in_arg, typ=BaseType("int256",), pos=getpos(expr))
        elif isinstance(in_arg, Decimal):
            if not SizeLimits.in_bounds("int256", math.trunc(in_arg)):
                raise InvalidLiteral(f"Number out of range: {math.trunc(in_arg)}")
            return LLLnode.from_list(math.trunc(in_arg), typ=BaseType("int256"), pos=getpos(expr))
        else:
            raise InvalidLiteral(f"Unknown numeric literal type: {in_arg}")
    elif isinstance(in_arg, LLLnode) and input_type == "int128":
        return LLLnode.from_list(in_arg, typ=BaseType("int256"), pos=getpos(expr))
    elif isinstance(in_arg, LLLnode) and input_type == "uint256":
        if version_check(begin="constantinople"):
            upper_bound = ["shl", 255, 1]
        else:
            upper_bound = -(2 ** 255)
        return LLLnode.from_list(
            ["uclamplt", in_arg, upper_bound], typ=BaseType("int256"), pos=getpos(expr)
        )
    elif isinstance(in_arg, LLLnode) and input_type == "decimal":
        return LLLnode.from_list(
            ["sdiv", in_arg, DECIMAL_DIVISOR], typ=BaseType("int256"), pos=getpos(expr),
        )
    elif isinstance(in_arg, LLLnode) and input_type == "bool":
        return LLLnode.from_list(in_arg, typ=BaseType("int256"), pos=getpos(expr))
    elif isinstance(in_arg, LLLnode) and input_type in ("bytes32", "address"):
        return LLLnode(
            value=in_arg.value, args=in_arg.args, typ=BaseType("int256"), pos=getpos(expr)
        )
    elif isinstance(in_arg, LLLnode) and input_type in ("Bytes", "String"):
        if in_arg.typ.maxlen > 32:
            raise TypeMismatch(
                f"Cannot convert bytes array of max length {in_arg.typ.maxlen} to int256", expr,
            )
        return byte_array_to_num(in_arg, expr, "int256")
    else:
        raise InvalidLiteral(f"Invalid input for int256: {in_arg}", expr)
def parse_internal_function(
    code: vy_ast.FunctionDef, sig: FunctionSignature, context: Context
) -> LLLnode:
    """
    Parse a internal function (FuncDef), and produce full function body.
    :param sig: the FuntionSignature
    :param code: ast of function
    :return: full sig compare & function body
    """
    func_type = code._metadata["type"]
    nonreentrant_pre, nonreentrant_post = get_nonreentrant_lock(func_type)
    clampers: List[LLLnode] = []
    context.memory_allocator.expand_memory(sig.max_copy_size)
    _post_callback_ptr = f"{sig.name}_{sig.method_id}_post_callback_ptr"
    context.callback_ptr = context.new_internal_variable(typ=BaseType("uint256"))
    clampers.append(
        LLLnode.from_list(
            ["mstore", context.callback_ptr, "pass"], annotation="pop callback pointer",
        )
    )
    if sig.total_default_args > 0:
        clampers.append(LLLnode.from_list(["label", _post_callback_ptr]))
    if sig.output_type is None:
        stop_func = [["jump", ["mload", context.callback_ptr]]]
    else:
        stop_func = [["stop"]]
    if len(sig.base_args) == 0:
        copier = ["pass"]
        clampers.append(LLLnode.from_list(copier))
    elif sig.total_default_args == 0:
        copier = get_internal_arg_copier(
            total_size=sig.base_copy_size, memory_dest=MemoryPositions.RESERVED_MEMORY
        )
        clampers.append(LLLnode.from_list(copier))
    for arg in sig.args:
        if isinstance(arg.typ, ByteArrayLike):
            mem_pos = context.memory_allocator.expand_memory(32 * get_size_of_type(arg.typ))
            context.vars[arg.name] = VariableRecord(arg.name, mem_pos, arg.typ, False)
        else:
            context.vars[arg.name] = VariableRecord(
                arg.name, MemoryPositions.RESERVED_MEMORY + arg.pos, arg.typ, False,
            )
    dyn_variable_names = [a.name for a in sig.base_args if isinstance(a.typ, ByteArrayLike)]
    if dyn_variable_names:
        i_placeholder = context.new_internal_variable(typ=BaseType("uint256"))
        unpackers: List[Any] = []
        for idx, var_name in enumerate(dyn_variable_names):
            var = context.vars[var_name]
            ident = f"_load_args_{sig.method_id}_dynarg{idx}"
            o = make_unpacker(ident=ident, i_placeholder=i_placeholder, begin_pos=var.pos)
            unpackers.append(o)
        if not unpackers:
            unpackers = ["pass"]
        unpackers.append(0)
        clampers.append(
            LLLnode.from_list(
                ["seq_unchecked"] + unpackers,
                typ=None,
                annotation="dynamic unpacker",
                pos=getpos(code),
            )
        )
    if sig.total_default_args > 0:
        default_sigs = sig_utils.generate_default_arg_sigs(code, context.sigs, context.global_ctx)
        sig_chain: List[Any] = ["seq"]
        for default_sig in default_sigs:
            sig_compare, internal_label = get_sig_statements(default_sig, getpos(code))
            set_defaults = []
            for arg_name in get_default_names_to_set(sig, default_sig):
                value = Expr(sig.default_values[arg_name], context).lll_node
                var = context.vars[arg_name]
                left = LLLnode.from_list(
                    var.pos, typ=var.typ, location="memory", pos=getpos(code), mutable=var.mutable
                )
                set_defaults.append(make_setter(left, value, "memory", pos=getpos(code)))
            current_sig_arg_names = [x.name for x in default_sig.args]
            copier_arg_count = len(default_sig.args)
            copier_arg_names = current_sig_arg_names
            copier_arg_names = [x.name for x in default_sig.args if x.name in copier_arg_names]
            default_copiers: List[Any] = []
            if copier_arg_count > 0:
                offset = 4
                calldata_offset_map = {}
                for arg in default_sig.args:
                    calldata_offset_map[arg.name] = offset
                    offset += (
                        32 if isinstance(arg.typ, ByteArrayLike) else get_size_of_type(arg.typ) * 32
                    )
                dynamics = []
                for arg_name in copier_arg_names:
                    var = context.vars[arg_name]
                    if isinstance(var.typ, ByteArrayLike):
                        _size = 32
                        dynamics.append(var.pos)
                    else:
                        _size = var.size * 32
                    default_copiers.append(
                        get_internal_arg_copier(memory_dest=var.pos, total_size=_size,)
                    )
                if dynamics:
                    i_placeholder = context.new_internal_variable(typ=BaseType("uint256"))
                    for idx, var_pos in enumerate(dynamics):
                        ident = f"unpack_default_sig_dyn_{default_sig.method_id}_arg{idx}"
                        default_copiers.append(
                            make_unpacker(
                                ident=ident, i_placeholder=i_placeholder, begin_pos=var_pos,
                            )
                        )
                default_copiers.append(0)
            sig_chain.append(
                [
                    "if",
                    sig_compare,
                    [
                        "seq",
                        internal_label,
                        LLLnode.from_list(
                            ["mstore", context.callback_ptr, "pass"],
                            annotation="pop callback pointer",
                            pos=getpos(code),
                        ),
                        ["seq"] + set_defaults if set_defaults else ["pass"],
                        ["seq_unchecked"] + default_copiers if default_copiers else ["pass"],
                        ["goto", _post_callback_ptr],
                    ],
                ]
            )
        _clampers = [["label", _post_callback_ptr]]
        return LLLnode.from_list(
            [
                "seq",
                sig_chain,
                ["seq"]
                + nonreentrant_pre
                + _clampers
                + [parse_body(c, context) for c in code.body]
                + nonreentrant_post
                + stop_func,
            ],
            typ=None,
            pos=getpos(code),
        )
    else:
        sig_compare, internal_label = get_sig_statements(sig, getpos(code))
        return LLLnode.from_list(
            ["seq"]
            + [internal_label]
            + nonreentrant_pre
            + clampers
            + [parse_body(c, context) for c in code.body]
            + nonreentrant_post
            + stop_func,
            typ=None,
            pos=getpos(code),
        )
class FunctionSignature:
    @classmethod
    def from_definition(
        cls,
        code,
        sigs=None,
        custom_structs=None,
        interface_def=False,
        constant_override=False,
        is_from_json=False,
    ):
        if not custom_structs:
            custom_structs = {}
        name = code.name
        mem_pos = 0
        args = []
        for arg in code.args.args:
            typ = arg.annotation
            parsed_type = parse_type(typ, None, sigs, custom_structs=custom_structs,)
            args.append(
                VariableRecord(arg.arg, mem_pos, parsed_type, False, defined_at=getpos(arg),)
            )
            if isinstance(parsed_type, ByteArrayLike):
                mem_pos += 32
            else:
                mem_pos += get_size_of_type(parsed_type) * 32
        mutability = "nonpayable"
        nonreentrant_key = ""
        is_internal = False
        for dec in code.decorator_list:
            if isinstance(dec, vy_ast.Name) and dec.id in ("payable", "view", "pure"):
                mutability = dec.id
            elif isinstance(dec, vy_ast.Name) and dec.id == "internal":
                is_internal = True
            elif isinstance(dec, vy_ast.Name) and dec.id == "external":
                is_internal = False
            elif isinstance(dec, vy_ast.Call) and dec.func.id == "nonreentrant":
                nonreentrant_key = dec.args[0].s
        if constant_override:
            if mutability == "payable":
                raise StructureException(f"Function {name} cannot be both constant and payable.")
            mutability = "view"
        output_type = None
        if code.returns:
            output_type = parse_type(code.returns, None, sigs, custom_structs=custom_structs,)
            assert isinstance(output_type, TupleType) or canonicalize_type(output_type)
        sig = cls.get_full_sig(name, code.args.args, sigs, custom_structs)
        method_id = fourbytes_to_int(keccak256(bytes(sig, "utf-8"))[:4])
        return cls(
            name,
            args,
            output_type,
            mutability,
            is_internal,
            nonreentrant_key,
            sig,
            method_id,
            code,
            is_from_json,
        )
def _check_return_body(node, node_list):
    return_count = len([n for n in node_list if is_return_from_function(n)])
    if return_count > 1:
        raise StructureException(
            "Too too many exit statements (return, raise or selfdestruct).", node
        )
    last_node_pos = len(node_list) - 1
    for idx, n in enumerate(node_list):
        if is_return_from_function(n) and idx < last_node_pos:
            raise StructureException(
                "Exit statement with succeeding code (that will not execute).", node_list[idx + 1]
            )
def get_nonreentrant_lock(func_type):
    nonreentrant_pre = [["pass"]]
    nonreentrant_post = [["pass"]]
    if func_type.nonreentrant:
        nkey = func_type.reentrancy_key_position.position
        nonreentrant_pre = [["seq", ["assert", ["iszero", ["sload", nkey]]], ["sstore", nkey, 1]]]
        nonreentrant_post = [["sstore", nkey, 0]]
    return nonreentrant_pre, nonreentrant_post
@apply_line_numbers
def _compile_to_assembly(code, withargs=None, existing_labels=None, break_dest=None, height=0):
        o = []

def check_external_call(call_ir):
    copy_revertdata = ["returndatacopy", 0, 0, "returndatasize"]
    revert = ["revert", 0, "returndatasize"]
    propagate_revert_ir = ["seq", copy_revertdata, revert]
    return ["if", ["iszero", call_ir], propagate_revert_ir]
def dynarray_data_ptr(ptr):
    if ptr.location is None:
        raise CompilerPanic("tried to modify non-pointer type")
    assert isinstance(ptr.typ, DArrayType)
    return add_ofst(ptr, ptr.location.word_scale)
def _dynarray_make_setter(dst, src):
    assert isinstance(src.typ, DArrayType)
    assert isinstance(dst.typ, DArrayType)
    if src.value == "~empty":
        return IRnode.from_list(STORE(dst, 0))
    if src.value == "multi":
        ret = ["seq"]
        store_length = STORE(dst, len(src.args))
        ann = None
        if src.annotation is not None:
            ann = f"len({src.annotation})"
        store_length = IRnode.from_list(store_length, annotation=ann)
        ret.append(store_length)
        n_items = len(src.args)
        for i in range(n_items):
            k = IRnode.from_list(i, typ="uint256")
            dst_i = get_element_ptr(dst, k, array_bounds_check=False)
            src_i = get_element_ptr(src, k, array_bounds_check=False)
            ret.append(make_setter(dst_i, src_i))
        return ret
    with src.cache_when_complex("darray_src") as (b1, src):
        should_loop = (
            src.encoding in (Encoding.ABI, Encoding.JSON_ABI)
            and src.typ.subtype.abi_type.is_dynamic()
        )
        should_loop |= src.typ.subtype.abi_type.is_dynamic()
        should_loop |= needs_clamp(src.typ.subtype, src.encoding)
        with get_dyn_array_count(src).cache_when_complex("darray_count") as (b2, count):
            ret = ["seq"]
            ret.append(STORE(dst, count))
            if should_loop:
                i = IRnode.from_list(_freshname("copy_darray_ix"), typ="uint256")
                loop_body = make_setter(
                    get_element_ptr(dst, i, array_bounds_check=False),
                    get_element_ptr(src, i, array_bounds_check=False),
                )
                loop_body.annotation = f"{dst}[i] = {src}[i]"
                ret.append(["repeat", i, 0, count, src.typ.count, loop_body])
            else:
                element_size = src.typ.subtype.memory_bytes_required
                n_bytes = _mul(count, element_size)
                max_bytes = src.typ.count * element_size
                src_ = dynarray_data_ptr(src)
                dst_ = dynarray_data_ptr(dst)
                ret.append(copy_bytes(dst_, src_, n_bytes, max_bytes))
            return b1.resolve(b2.resolve(ret))
def copy_bytes(dst, src, length, length_bound):
    annotation = f"copy_bytes from {src} to {dst}"
    src = IRnode.from_list(src)
    dst = IRnode.from_list(dst)
    length = IRnode.from_list(length)
    with src.cache_when_complex("src") as (b1, src), length.cache_when_complex(
        "copy_bytes_count"
    ) as (b2, length), dst.cache_when_complex("dst") as (b3, dst):
        if length_bound <= 32:
            copy_op = STORE(dst, LOAD(src))
            ret = IRnode.from_list(copy_op, annotation=annotation)
            return b1.resolve(b2.resolve(b3.resolve(ret)))
        if dst.location == MEMORY and src.location in (MEMORY, CALLDATA, DATA):
            if src.location == MEMORY:
                copy_op = ["staticcall", "gas", 4, src, length, dst, length]
                gas_bound = _identity_gas_bound(length_bound)
            elif src.location == CALLDATA:
                copy_op = ["calldatacopy", dst, src, length]
                gas_bound = _calldatacopy_gas_bound(length_bound)
            elif src.location == DATA:
                copy_op = ["dloadbytes", dst, src, length]
                gas_bound = _codecopy_gas_bound(length_bound)
            ret = IRnode.from_list(copy_op, annotation=annotation, add_gas_estimate=gas_bound)
            return b1.resolve(b2.resolve(b3.resolve(ret)))
        if dst.location == IMMUTABLES and src.location in (MEMORY, DATA):
            pass
        i = IRnode.from_list(_freshname("copy_bytes_ix"), typ="uint256")
        n = ["div", ["ceil32", length], 32]
        n_bound = ceil32(length_bound) // 32
        dst_i = add_ofst(dst, _mul(i, dst.location.word_scale))
        src_i = add_ofst(src, _mul(i, src.location.word_scale))
        copy_one_word = STORE(dst_i, LOAD(src_i))
        main_loop = ["repeat", i, 0, n, n_bound, copy_one_word]
        return b1.resolve(
            b2.resolve(b3.resolve(IRnode.from_list(main_loop, annotation=annotation)))
        )
def get_dyn_array_count(arg):
    assert isinstance(arg.typ, DArrayType)
    typ = BaseType("uint256")
    if arg.value == "multi":
        return IRnode.from_list(len(arg.args), typ=typ)
    if arg.value == "~empty":
        return IRnode.from_list(0, typ=typ)
    return IRnode.from_list(LOAD(arg), typ=typ)
def getpos(node):
    return (
        node.lineno,
        node.col_offset,
        getattr(node, "end_lineno", None),
        getattr(node, "end_col_offset", None),
    )
def add_ofst(ptr, ofst):
    ret = ["add", ptr, ofst]
    return IRnode.from_list(ret, location=ptr.location, encoding=ptr.encoding)
def _mul(x, y):
    ret = ["mul", x, y]
    return IRnode.from_list(ret)
def _getelemptr_abi_helper(parent, member_t, ofst, clamp=True):
    member_abi_t = member_t.abi_type
    if has_length_word(parent.typ):
        parent = add_ofst(parent, parent.location.word_scale * DYNAMIC_ARRAY_OVERHEAD)
    ofst_ir = add_ofst(parent, ofst)
    if member_abi_t.is_dynamic():
        ofst_ir = add_ofst(parent, unwrap_location(ofst_ir))
    return IRnode.from_list(
        ofst_ir,
        typ=member_t,
        location=parent.location,
        encoding=parent.encoding,
        annotation=f"{parent}{ofst}",
    )
def _get_element_ptr_tuplelike(parent, key):
    typ = parent.typ
    assert isinstance(typ, TupleLike)
    if isinstance(typ, StructType):
        assert isinstance(key, str)
        subtype = typ.members[key]
        attrs = list(typ.tuple_keys())
        index = attrs.index(key)
        annotation = key
    else:
        assert isinstance(key, int)
        subtype = typ.members[key]
        attrs = list(range(len(typ.members)))
        index = key
        annotation = None
    if parent.value == "~empty":
        return IRnode.from_list("~empty", typ=subtype)
    if parent.value == "multi":
        assert parent.encoding != Encoding.ABI, "no abi-encoded literals"
        return parent.args[index]
    ofst = 0
    if parent.encoding in (Encoding.ABI, Encoding.JSON_ABI):
        if parent.location == STORAGE:
            raise CompilerPanic("storage variables should not be abi encoded")
        member_t = typ.members[attrs[index]]
        for i in range(index):
            member_abi_t = typ.members[attrs[i]].abi_type
            ofst += member_abi_t.embedded_static_size()
        return _getelemptr_abi_helper(parent, member_t, ofst)
    if parent.location.word_addressable:
        for i in range(index):
            ofst += typ.members[attrs[i]].storage_size_in_words
    elif parent.location.byte_addressable:
        for i in range(index):
            ofst += typ.members[attrs[i]].memory_bytes_required
    else:
        raise CompilerPanic(f"bad location {parent.location}")
    return IRnode.from_list(
        add_ofst(parent, ofst),
        typ=subtype,
        location=parent.location,
        encoding=parent.encoding,
        annotation=annotation,
    )
