class Slice:
    @validate_inputs
    def build_IR(self, expr, args, kwargs, context):
        src, start, length = args
        if src.value in ADHOC_SLICE_NODE_MACROS:
            return _build_adhoc_slice_node(src, start, length, context)
        is_bytes32 = is_base_type(src.typ, "bytes32")
        if src.location is None:
            assert is_bytes32, src
            src = ensure_in_memory(src, context)
        with src.cache_when_complex("src") as (b1, src), start.cache_when_complex("start") as (
            b2,
            start,
        ), length.cache_when_complex("length") as (b3, length):
            if is_bytes32:
                src_maxlen = 32
            else:
                src_maxlen = src.typ.maxlen
            dst_maxlen = length.value if length.is_literal else src_maxlen
            buflen = dst_maxlen
            if src.location == STORAGE:
                buflen += 32
            assert isinstance(src.typ, ByteArrayLike) or is_bytes32
            if isinstance(src.typ, StringType):
                dst_typ = StringType(maxlen=dst_maxlen)
            else:
                dst_typ = ByteArrayType(maxlen=dst_maxlen)
            buf = context.new_internal_variable(ByteArrayType(buflen))
            dst = IRnode.from_list(buf, typ=dst_typ, location=MEMORY)
            dst_data = bytes_data_ptr(dst)
            if is_bytes32:
                src_len = 32
                src_data = src
            else:
                src_len = get_bytearray_length(src)
                src_data = bytes_data_ptr(src)
            if src.location == STORAGE:
                copy_src = IRnode.from_list(
                    ["add", src_data, ["div", start, 32]],
                    location=src.location,
                )
                copy_dst = IRnode.from_list(
                    ["sub", dst_data, ["mod", start, 32]], location=dst.location
                )
                copy_len = ["add", length, ["mul", 32, ["iszero", ["iszero", ["mod", start, 32]]]]]
                copy_maxlen = buflen
            else:
                copy_src = add_ofst(src_data, start)
                copy_dst = dst_data
                copy_len = length
                copy_maxlen = buflen
            do_copy = copy_bytes(
                copy_dst,
                copy_src,
                copy_len,
                copy_maxlen,
            )
            ret = [
                "seq",
                ["assert", ["le", ["add", start, length], src_len]],
                do_copy,
                ["mstore", dst, length],
                dst,
            ]
            ret = IRnode.from_list(ret, typ=dst_typ, location=MEMORY)
            return b1.resolve(b2.resolve(b3.resolve(ret)))
class RawCall(_SimpleBuiltinFunction):
    @validate_inputs
    def build_IR(self, expr, args, kwargs, context):
        to, data = args
        gas, value, outsize, delegate_call, static_call, revert_on_failure = (
            kwargs["gas"],
            kwargs["value"],
            kwargs["max_outsize"],
            kwargs["is_delegate_call"],
            kwargs["is_static_call"],
            kwargs["revert_on_failure"],
        )
        for key in ("is_delegate_call", "is_static_call", "revert_on_failure"):
            if kwargs[key].typ.is_literal is False:
                raise TypeMismatch(
                    f"The `{key}` parameter must be a static/literal boolean value", expr
                )
        revert_on_failure = revert_on_failure.value == 1
        static_call = static_call.value == 1
        delegate_call = delegate_call.value == 1
        if delegate_call and static_call:
            raise ArgumentException(
                "Call may use one of `is_delegate_call` or `is_static_call`, not both", expr
            )
        if not static_call and context.is_constant():
            raise StateAccessViolation(
                f"Cannot make modifying calls from {context.pp_constancy()},"
                " use `is_static_call=True` to perform this action",
                expr,
            )
        eval_input_buf = ensure_in_memory(data, context)
        input_buf = eval_seq(eval_input_buf)
        output_node = IRnode.from_list(
            context.new_internal_variable(ByteArrayType(outsize)),
            typ=ByteArrayType(outsize),
            location=MEMORY,
        )
        bool_ty = BaseType("bool")
        if input_buf is None:
            call_ir = ["with", "arg_buf", eval_input_buf]
            input_buf = IRnode.from_list("arg_buf")
        else:
            call_ir = ["seq", eval_input_buf]
        common_call_args = [
            add_ofst(input_buf, 32),
            ["mload", input_buf],
            add_ofst(output_node, 32) if outsize else 0,
            outsize,
        ]
        if delegate_call:
            call_op = ["delegatecall", gas, to, *common_call_args]
        elif static_call:
            call_op = ["staticcall", gas, to, *common_call_args]
        else:
            call_op = ["call", gas, to, value, *common_call_args]
        call_ir += [call_op]
        if outsize:
            size = [
                "with",
                "_l",
                outsize,
                ["with", "_r", "returndatasize", ["if", ["gt", "_l", "_r"], "_r", "_l"]],
            ]
            store_output_size = [
                "with",
                "output_pos",
                output_node,
                ["seq", ["mstore", "output_pos", size], "output_pos"],
            ]
            bytes_ty = ByteArrayType(outsize)
            if revert_on_failure:
                typ = bytes_ty
                ret_ir = ["seq", check_external_call(call_ir), store_output_size]
            else:
                typ = TupleType([bool_ty, bytes_ty])
                ret_ir = [
                    "multi",
                    IRnode.from_list(call_ir, typ=bool_ty),
                    IRnode.from_list(store_output_size, typ=bytes_ty, location=MEMORY),
                ]
        else:
            if revert_on_failure:
                typ = None
                ret_ir = check_external_call(call_ir)
            else:
                typ = bool_ty
                ret_ir = call_ir
        return IRnode.from_list(ret_ir, typ=typ, location=MEMORY)
class Sqrt(_SimpleBuiltinFunction):
    @validate_inputs
    def build_IR(self, expr, args, kwargs, context):
        from vyper.builtin_functions.utils import generate_inline_function
        arg = args[0]
        sqrt_code = """
assert x >= 0.0
z: decimal = 0.0
if x == 0.0:
    z = 0.0
else:
    z = x / 2.0 + 0.5
    y: decimal = x
    for i in range(256):
        if z == y:
            break
        y = z
        z = (x / z + z) / 2.0
        """
        x_type = BaseType("decimal")
        placeholder_copy = ["pass"]
        if arg.value == "mload":
            new_var_pos = arg.args[0]
        else:
            new_var_pos = context.new_internal_variable(x_type)
            placeholder_copy = ["mstore", new_var_pos, arg]
        variables = {"x": VariableRecord(name="x", pos=new_var_pos, typ=x_type, mutable=False)}
        new_ctx, sqrt_ir = generate_inline_function(
            code=sqrt_code, variables=variables, memory_allocator=context.memory_allocator
        )
        return IRnode.from_list(
            [
                "seq",
                placeholder_copy,
                sqrt_ir,
                new_ctx.vars["z"].pos,
            ],
            typ=BaseType("decimal"),
            location=MEMORY,
        )
class ABIEncode(_SimpleBuiltinFunction):
    def build_IR(self, expr, context):
        method_id = self._method_id(expr)
        args = [Expr(arg, context).ir_node for arg in expr.args]
        if len(args) < 1:
            raise StructureException("abi_encode expects at least one argument", expr)
        if len(args) == 1 and not self._ensure_tuple(expr):
            encode_input = args[0]
        else:
            encode_input = ir_tuple_from_args(args)
        input_abi_t = encode_input.typ.abi_type
        maxlen = input_abi_t.size_bound()
        if method_id is not None:
            maxlen += 4
        buf_t = ByteArrayType(maxlen=maxlen)
        buf = context.new_internal_variable(buf_t)
        ret = ["seq"]
        if method_id is not None:
            ret += [["mstore", buf + 4, method_id]]
            length = abi_encode(buf + 36, encode_input, context, returns_len=True, bufsz=maxlen)
            ret += [["mstore", buf, ["add", length, 4]]]
        else:
            length = abi_encode(buf + 32, encode_input, context, returns_len=True, bufsz=maxlen)
            ret += [["mstore", buf, length]]
        ret += [buf]
        return IRnode.from_list(
            ret,
            location=MEMORY,
            typ=buf_t,
            annotation=f"abi_encode builtin ensure_tuple={self._ensure_tuple(expr)}",
        )
class Stmt:
    def _assert_reason(self, test_expr, msg):
        if isinstance(msg, vy_ast.Name) and msg.id == "UNREACHABLE":
            return IRnode.from_list(["assert_unreachable", test_expr])
        try:
            tmp = self.context.constancy
            self.context.constancy = Constancy.Constant
            msg_ir = Expr(msg, self.context).ir_node
        finally:
            self.context.constancy = tmp
        def _get_last(ir):
            if len(ir.args) == 0:
                return ir.value
            return _get_last(ir.args[-1])
        if msg_ir.location != MEMORY:
            buf = self.context.new_internal_variable(msg_ir.typ)
            instantiate_msg = make_byte_array_copier(buf, msg_ir)
        else:
            buf = _get_last(msg_ir)
            if not isinstance(buf, int):
                raise CompilerPanic(f"invalid bytestring {buf}\n{self}")
            instantiate_msg = msg_ir
        method_id = util.abi_method_id("Error(string)")
        assert buf >= 36, "invalid buffer"
        _runtime_length = ["mload", buf]
        revert_seq = [
            "seq",
            instantiate_msg,
            zero_pad(buf),
            ["mstore", buf - 64, method_id],
            ["mstore", buf - 32, 0x20],
            ["revert", buf - 36, ["add", 4 + 32 + 32, ["ceil32", _runtime_length]]],
        ]
        if test_expr is not None:
            ir_node = ["if", ["iszero", test_expr], revert_seq]
        else:
            ir_node = revert_seq
        return IRnode.from_list(ir_node)
    def _parse_For_list(self):
        with self.context.range_scope():
            iter_list = Expr(self.stmt.iter, self.context).ir_node
        target_type = new_type_to_old_type(self.stmt.target._metadata["type"])
        iter_list.typ.subtype = target_type
        varname = self.stmt.target.id
        loop_var = IRnode.from_list(
            self.context.new_variable(varname, target_type), typ=target_type, location=MEMORY
        )
        i = IRnode.from_list(self.context.fresh_varname("for_list_ix"), typ="uint256")
        self.context.forvars[varname] = True
        ret = ["seq"]
        if isinstance(self.stmt.iter, vy_ast.List):
            tmp_list = IRnode.from_list(
                self.context.new_internal_variable(iter_list.typ),
                typ=iter_list.typ,
                location=MEMORY,
            )
            ret.append(make_setter(tmp_list, iter_list))
            iter_list = tmp_list
        e = get_element_ptr(iter_list, i, array_bounds_check=False)
        body = [
            "seq",
            make_setter(loop_var, e),
            parse_body(self.stmt.body, self.context),
        ]
        repeat_bound = iter_list.typ.count
        if isinstance(iter_list.typ, DArrayType):
            array_len = get_dyn_array_count(iter_list)
        else:
            array_len = repeat_bound
        ret.append(["repeat", i, 0, array_len, repeat_bound, body])
        del self.context.forvars[varname]
        return IRnode.from_list(ret)
    def _get_target(self, target):
        _dbg_expr = target
        if isinstance(target, vy_ast.Name) and target.id in self.context.forvars:
            raise TypeCheckFailure(f"Failed constancy check\n{_dbg_expr}")
        if isinstance(target, vy_ast.Tuple):
            target = Expr(target, self.context).ir_node
            for node in target.args:
                if (node.location == STORAGE and self.context.is_constant()) or not node.mutable:
                    raise TypeCheckFailure(f"Failed constancy check\n{_dbg_expr}")
            return target
        target = Expr.parse_pointer_expr(target, self.context)
        if (target.location == STORAGE and self.context.is_constant()) or not target.mutable:
            raise TypeCheckFailure(f"Failed constancy check\n{_dbg_expr}")
        return target
def make_return_stmt(ir_val: IRnode, stmt: Any, context: Context) -> Optional[IRnode]:
    sig = context.sig
    jump_to_exit = ["exit_to", f"_sym_{sig.exit_sequence_label}"]
    if context.return_type is None:
        if stmt.value is not None:
            return None
    else:
        check_assign(dummy_node_for_type(context.return_type), ir_val)
    def finalize(fill_return_buffer):
        fill_return_buffer = IRnode.from_list(
            fill_return_buffer, annotation=f"fill return buffer {sig._ir_identifier}"
        )
        cleanup_loops = "cleanup_repeat" if context.forvars else "pass"
        return IRnode.from_list(["seq", fill_return_buffer, cleanup_loops, jump_to_exit])
    if context.return_type is None:
        jump_to_exit += ["return_pc"]
        return finalize(["pass"])
    if context.is_internal:
        dst = IRnode.from_list(["return_buffer"], typ=context.return_type, location=MEMORY)
        fill_return_buffer = make_setter(dst, ir_val)
        jump_to_exit += ["return_pc"]
        return finalize(fill_return_buffer)
    else:
        external_return_type = calculate_type_for_external_return(context.return_type)
        maxlen = external_return_type.abi_type.size_bound()
        can_skip_encode = (
            abi_encoding_matches_vyper(ir_val.typ)
            and ir_val.location == MEMORY
            and not needs_clamp(ir_val.typ, ir_val.encoding)
        )
        if can_skip_encode:
            assert ir_val.typ.memory_bytes_required == maxlen
            jump_to_exit += [ir_val, maxlen]
            return finalize(["pass"])
        ir_val = wrap_value_for_external_return(ir_val)
        return_buffer_ofst = context.new_internal_variable(get_type_for_exact_size(maxlen))
        return_len = abi_encode(return_buffer_ofst, ir_val, context, returns_len=True, bufsz=maxlen)
        jump_to_exit += [return_buffer_ofst, return_len]
        return finalize(["pass"])
MEMORY = AddrSpace("memory", 32, "mload", "mstore")
STORAGE = AddrSpace("storage", 1, "sload", "sstore")
CALLDATA = AddrSpace("calldata", 32, "calldataload")

class Extractor(Module):
    UNIQUE_PATH_DELIMITER = '%%'
    def build_output_directory(self, path):
        '''
        Set the output directory for extracted files.
        @path - The path to the file that data will be extracted from.
        Returns None.
        '''
        if not has_key(self.extraction_directories, path):
            basedir = os.path.dirname(path)
            basename = os.path.basename(path)
            if basedir != self.directory:
                try:
                    subdir = basedir.split(self.directory)[1][1:]
                except IndexError as e:
                    subdir = ""
            else:
                subdir = ""
            if self.output_directory_override:
                output_directory = os.path.join(self.directory, subdir, self.output_directory_override)
            else:
                outdir = os.path.join(self.directory, subdir, '_' + basename)
                output_directory = unique_file_name(outdir, extension='extracted')
            if not os.path.exists(output_directory):
                os.mkdir(output_directory)
            self.extraction_directories[path] = output_directory
            self.output[path].directory = os.path.realpath(output_directory) + os.path.sep
        else:
            output_directory = self.extraction_directories[path]
        return output_directory
    def extract(self, offset, description, file_name, size, name=None):
        '''
        Extract an embedded file from the target file, if it matches an extract rule.
        Called automatically by Binwalk.scan().
        @offset      - Offset inside the target file to begin the extraction.
        @description - Description of the embedded file to extract, as returned by libmagic.
        @file_name   - Path to the target file.
        @size        - Number of bytes to extract.
        @name        - Name to save the file as.
        Returns the name of the extracted file (blank string if nothing was extracted).
        '''
        fname = ''
        rule = None
        recurse = False
        command_line = ''
        original_dir = os.getcwd()
        rules = self.match(description)
        file_path = os.path.realpath(file_name)
        if not rules:
            binwalk.core.common.debug("No extraction rules found for '%s'" % description)
            return (None, None, False, str(None))
        else:
            binwalk.core.common.debug("Found %d matching extraction rules" % len(rules))
        output_directory = self.build_output_directory(file_name)
        if not size:
            size = file_size(file_path) - offset
        if os.path.isfile(file_path):
            binwalk.core.common.debug("Changing directory to: %s" % output_directory)
            os.chdir(output_directory)
            if self.extract_into_subdirs:
                offset_dir = "0x%X" % offset
                os.mkdir(offset_dir)
                os.chdir(offset_dir)
            for i in range(0, len(rules)):
                rule = rules[i]
                binwalk.core.common.debug("Processing extraction rule
                if rule['recurse'] in [True, False]:
                    recurse = rule['recurse']
                else:
                    recurse = True
                binwalk.core.common.debug("Extracting %s[%d:] to %s" % (file_path, offset, name))
                fname = self._dd(file_path, offset, size, rule['extension'], output_file_name=name)
                if rule['cmd']:
                    if self.remove_after_execute:
                        fname_md5 = file_md5(fname)
                    binwalk.core.common.debug("Executing extraction command %s" % (str(rule['cmd'])))
                    if self.run_extractors:
                        (extract_ok, command_line) = self.execute(rule['cmd'], fname, rule['codes'])
                    else:
                        extract_ok = True
                        command_line = ''
                    binwalk.core.common.debug("Ran extraction command: %s" % command_line)
                    binwalk.core.common.debug("Extraction successful: %s" % extract_ok)
                    if self.remove_after_execute and (extract_ok == True or i == (len(rules) - 1)):
                        try:
                            if file_md5(fname) == fname_md5:
                                os.unlink(fname)
                        except KeyboardInterrupt as e:
                            raise e
                        except Exception as e:
                            pass
                    if extract_ok == True:
                        break
                    elif i != (len(rules) - 1):
                        try:
                            os.unlink(fname)
                        except KeyboardInterrupt as e:
                            raise e
                        except Exception as e:
                            pass
                else:
                    break
            binwalk.core.common.debug("Changing directory back to: %s" % original_dir)
            os.chdir(original_dir)
        return (output_directory, fname, recurse, command_line)
    def match(self, description):
        '''
        Check to see if the provided description string matches an extract rule.
        Called internally by self.extract().
        @description - Description string to check.
        Returns the associated rule dictionary if a match is found.
        Returns None if no match is found.
        '''
        rules = []
        ordered_rules = []
        description = description.lower()
        for rule in self.extract_rules:
            if rule['regex'].search(description):
                rules.append(rule)
        for rule in rules:
            if callable(rule['cmd']):
                ordered_rules.append(rule)
        for rule in rules:
            if not callable(rule['cmd']):
                ordered_rules.append(rule)
        binwalk.core.common.debug("Found %d/%d matches for '%s'" % (len(ordered_rules), len(self.extract_rules), description))
        return ordered_rules
    def execute(self, cmd, fname, codes=[0, None]):
        '''
        Execute a command against the specified file.
        @cmd   - Command to execute.
        @fname - File to run command against.
        @codes - List of return codes indicating cmd success.
        Returns True on success, False on failure, or None if the external extraction utility could not be found.
        '''
        tmp = None
        rval = 0
        retval = True
        command_list = []
        binwalk.core.common.debug("Running extractor '%s'" % str(cmd))
        try:
            if callable(cmd):
                command_list.append(get_class_name_from_method(cmd))
                try:
                    retval = cmd(fname)
                except KeyboardInterrupt as e:
                    raise e
                except Exception as e:
                    retval = False
                    binwalk.core.common.warning("Internal extractor '%s' failed with exception: '%s'" % (str(cmd), str(e)))
            elif cmd:
                if not binwalk.core.common.DEBUG:
                    tmp = tempfile.TemporaryFile()
                while self.UNIQUE_PATH_DELIMITER in cmd:
                    need_unique_path = cmd.split(self.UNIQUE_PATH_DELIMITER)[
                        1].split(self.UNIQUE_PATH_DELIMITER)[0]
                    unique_path = binwalk.core.common.unique_file_name(need_unique_path)
                    cmd = cmd.replace(self.UNIQUE_PATH_DELIMITER + need_unique_path + self.UNIQUE_PATH_DELIMITER, unique_path)
                for command in cmd.split("&&"):
                    command = command.strip().replace(self.FILE_NAME_PLACEHOLDER, fname)
                    binwalk.core.common.debug("subprocess.call(%s, stdout=%s, stderr=%s)" % (command, str(tmp), str(tmp)))
                    rval = subprocess.call(shlex.split(command), stdout=tmp, stderr=tmp)
                    if rval in codes:
                        retval = True
                    else:
                        retval = False
                    binwalk.core.common.debug('External extractor command "%s" completed with return code %d (success: %s)' % (cmd, rval, str(retval)))
                    command_list.append(command)
        except KeyboardInterrupt as e:
            raise e
        except Exception as e:
            binwalk.core.common.warning("Extractor.execute failed to run external extractor '%s': %s, '%s' might not be installed correctly" % (str(cmd), str(e), str(cmd)))
            retval = None
        if tmp is not None:
            tmp.close()
        return (retval, '&&'.join(command_list))

class Extractor(Module):
    UNIQUE_PATH_DELIMITER = '%%'
    def callback(self, r):
        try:
            r.file.size
        except KeyboardInterrupt as e:
            pass
        except Exception as e:
            return
        if not r.size:
            size = r.file.size - r.offset
        else:
            size = r.size
        if r.valid and r.extract and r.display and (not self.max_count or self.extraction_count < self.max_count):
            if not binwalk.core.common.has_key(self.output, r.file.path):
                self.output[r.file.path] = ExtractInfo()
            binwalk.core.common.debug("Extractor callback for %s @%d [%s]" % (r.file.name,
                                                                              r.offset,
                                                                              r.description))
            (extraction_directory, dd_file, scan_extracted_files, extraction_utility) = self.extract(r.offset,
                                                                                                     r.description,
                                                                                                     r.file.path,
                                                                                                     size,
                                                                                                     r.name)
            if extraction_directory and dd_file:
                self.extraction_count += 1
                dd_file_path = os.path.join(extraction_directory, dd_file)
                self.output[r.file.path].carved[r.offset] = dd_file_path
                self.output[r.file.path].extracted[r.offset] = ExtractDetails(files=[], command=extraction_utility)
                directory_listing = set(os.listdir(extraction_directory))
                if not has_key(self.last_directory_listing, extraction_directory):
                    self.last_directory_listing[extraction_directory] = set()
                for f in directory_listing.difference(self.last_directory_listing[extraction_directory]):
                    file_path = os.path.join(extraction_directory, f)
                    real_file_path = os.path.realpath(file_path)
                    self.result(description=file_path, display=False)
                    if real_file_path != dd_file_path:
                        binwalk.core.common.debug("Adding %s (%s) (%s) to file list" % (file_path, f, real_file_path))
                        self.output[r.file.path].extracted[r.offset].files.append(file_path)
                    if file_path != dd_file_path:
                        self.symlink_sanitizer(file_path, extraction_directory)
                        if os.path.isdir(file_path):
                            for root, dirs, files in os.walk(file_path):
                                self.symlink_sanitizer([os.path.join(root, x) for x in dirs+files], extraction_directory)
                                for f in files:
                                    full_path = os.path.join(root, f)
                                    if len(real_file_path.split(self.directory)[1].split(os.path.sep)) <= self.matryoshka:
                                        if scan_extracted_files and self.directory in real_file_path:
                                                self.add_pending(full_path)
                        elif scan_extracted_files and self.directory in real_file_path:
                            self.add_pending(file_path)
                self.last_directory_listing[extraction_directory] = directory_listing
    def build_output_directory(self, path):
        '''
        Set the output directory for extracted files.
        @path - The path to the file that data will be extracted from.
        Returns None.
        '''
        if not has_key(self.extraction_directories, path):
            basedir = os.path.dirname(path)
            basename = os.path.basename(path)
            if basedir != self.directory:
                try:
                    subdir = basedir.split(self.directory)[1][1:]
                except IndexError as e:
                    subdir = ""
            else:
                subdir = ""
            if self.output_directory_override:
                output_directory = os.path.join(self.directory, subdir, self.output_directory_override)
            else:
                outdir = os.path.join(self.directory, subdir, '_' + basename)
                output_directory = unique_file_name(outdir, extension='extracted')
            if not os.path.exists(output_directory):
                os.mkdir(output_directory)
            self.extraction_directories[path] = output_directory
            self.output[path].directory = os.path.realpath(output_directory) + os.path.sep
        else:
            output_directory = self.extraction_directories[path]
        os.chown(output_directory, self.runas_uid, self.runas_gid)
        return output_directory
    def extract(self, offset, description, file_name, size, name=None):
        '''
        Extract an embedded file from the target file, if it matches an extract rule.
        Called automatically by Binwalk.scan().
        @offset      - Offset inside the target file to begin the extraction.
        @description - Description of the embedded file to extract, as returned by libmagic.
        @file_name   - Path to the target file.
        @size        - Number of bytes to extract.
        @name        - Name to save the file as.
        Returns the name of the extracted file (blank string if nothing was extracted).
        '''
        fname = ''
        rule = None
        recurse = False
        command_line = ''
        original_dir = os.getcwd()
        rules = self.match(description)
        file_path = os.path.realpath(file_name)
        if not rules:
            binwalk.core.common.debug("No extraction rules found for '%s'" % description)
            return (None, None, False, str(None))
        else:
            binwalk.core.common.debug("Found %d matching extraction rules" % len(rules))
        output_directory = self.build_output_directory(file_name)
        if not size:
            size = file_size(file_path) - offset
        if os.path.isfile(file_path):
            binwalk.core.common.debug("Changing directory to: %s" % output_directory)
            os.chdir(output_directory)
            if self.extract_into_subdirs:
                offset_dir = "0x%X" % offset
                os.mkdir(offset_dir)
                os.chdir(offset_dir)
            for i in range(0, len(rules)):
                rule = rules[i]
                binwalk.core.common.debug("Processing extraction rule
                if rule['recurse'] in [True, False]:
                    recurse = rule['recurse']
                else:
                    recurse = True
                binwalk.core.common.debug("Extracting %s[%d:] to %s" % (file_path, offset, name))
                fname = self._dd(file_path, offset, size, rule['extension'], output_file_name=name)
                if rule['cmd']:
                    if self.remove_after_execute:
                        fname_md5 = file_md5(fname)
                    binwalk.core.common.debug("Executing extraction command %s" % (str(rule['cmd'])))
                    if self.run_extractors:
                        (extract_ok, command_line) = self.execute(rule['cmd'], fname, rule['codes'])
                    else:
                        extract_ok = True
                        command_line = ''
                    binwalk.core.common.debug("Ran extraction command: %s" % command_line)
                    binwalk.core.common.debug("Extraction successful: %s" % extract_ok)
                    if self.remove_after_execute and (extract_ok == True or i == (len(rules) - 1)):
                        try:
                            if file_md5(fname) == fname_md5:
                                os.unlink(fname)
                        except KeyboardInterrupt as e:
                            raise e
                        except Exception as e:
                            pass
                    if extract_ok == True:
                        break
                    elif i != (len(rules) - 1):
                        try:
                            os.unlink(fname)
                        except KeyboardInterrupt as e:
                            raise e
                        except Exception as e:
                            pass
                else:
                    break
            binwalk.core.common.debug("Changing directory back to: %s" % original_dir)
            os.chdir(original_dir)
        return (output_directory, fname, recurse, command_line)
    def match(self, description):
        '''
        Check to see if the provided description string matches an extract rule.
        Called internally by self.extract().
        @description - Description string to check.
        Returns the associated rule dictionary if a match is found.
        Returns None if no match is found.
        '''
        rules = []
        ordered_rules = []
        description = description.lower()
        for rule in self.extract_rules:
            if rule['regex'].search(description):
                rules.append(rule)
        for rule in rules:
            if callable(rule['cmd']):
                ordered_rules.append(rule)
        for rule in rules:
            if not callable(rule['cmd']):
                ordered_rules.append(rule)
        binwalk.core.common.debug("Found %d/%d matches for '%s'" % (len(ordered_rules), len(self.extract_rules), description))
        return ordered_rules
    def execute(self, cmd, fname, codes=[0, None]):
        '''
        Execute a command against the specified file.
        @cmd   - Command to execute.
        @fname - File to run command against.
        @codes - List of return codes indicating cmd success.
        Returns True on success, False on failure, or None if the external extraction utility could not be found.
        '''
        rval = 0
        retval = True
        command_list = []
        binwalk.core.common.debug("Running extractor '%s'" % str(cmd))
        try:
            if callable(cmd):
                command_list.append(get_class_name_from_method(cmd))
                try:
                    retval = cmd(fname)
                except KeyboardInterrupt as e:
                    raise e
                except Exception as e:
                    retval = False
                    binwalk.core.common.warning("Internal extractor '%s' failed with exception: '%s'" % (str(cmd), str(e)))
            elif cmd:
                while self.UNIQUE_PATH_DELIMITER in cmd:
                    need_unique_path = cmd.split(self.UNIQUE_PATH_DELIMITER)[1].split(self.UNIQUE_PATH_DELIMITER)[0]
                    unique_path = binwalk.core.common.unique_file_name(need_unique_path)
                    cmd = cmd.replace(self.UNIQUE_PATH_DELIMITER + need_unique_path + self.UNIQUE_PATH_DELIMITER, unique_path)
                for command in cmd.split("&&"):
                    command = command.strip().replace(self.FILE_NAME_PLACEHOLDER, fname)
                    rval = self.shell_call(command)
                    if rval in codes:
                        retval = True
                    else:
                        retval = False
                    binwalk.core.common.debug('External extractor command "%s" completed with return code %d (success: %s)' % (cmd, rval, str(retval)))
                    command_list.append(command)
        except KeyboardInterrupt as e:
            raise e
        except Exception as e:
            binwalk.core.common.warning("Extractor.execute failed to run external extractor '%s': %s, '%s' might not be installed correctly" % (str(cmd), str(e), str(cmd)))
            retval = None
        return (retval, '&&'.join(command_list))
    def shell_call(self, command):
        if not binwalk.core.common.DEBUG:
            tmp = subprocess.DEVNULL
        else:
            tmp = None
        if self.runas_uid != os.getuid():
            binwalk.core.common.debug("Switching privileges to %s (%d:%d)" % (self.runas_user, self.runas_uid, self.runas_gid))
            child_pid = os.fork()
            if child_pid is 0:
                if self.runas_uid is not None and self.runas_gid is not None:
                    os.setgid(self.runas_uid)
                    os.setuid(self.runas_gid)
        else:
            child_pid = None
        if child_pid in [0, None]:
            binwalk.core.common.debug("subprocess.call(%s, stdout=%s, stderr=%s)" % (command, str(tmp), str(tmp)))
            rval = subprocess.call(shlex.split(command), stdout=tmp, stderr=tmp)
        if child_pid is 0:
            sys.exit(rval)
        elif child_pid is None:
            return rval
        else:
            return os.wait()[1]

