        for x in int_keys:
            if l < x <= 0:
                str_keys.append(x)
                del int_keys[int_keys.index(x)]
        int_keys.sort()
        if len(int_keys) > 0 and int_keys[0] != 0:
            for x in int_keys:
                str_keys.append(str(x))
