        raise ValueError(f"Quote was expected to use {exp_hash_alg} but used {hashfunc.name} instead")
    digest = hashes.Hash(hashfunc, backend=backends.default_backend())
    digest.update(quoteblob)
    quote_digest = digest.finalize()
