    len_ = get_dyn_array_count(ir_node)
    with len_.cache_when_complex("len") as (b, len_):
        ret.append(STORE(dst, len_))
        t = UINT256_T
        i = IRnode.from_list(context.fresh_varname("ix"), typ=t)
