        body = ["seq", make_setter(loop_var, e), parse_body(self.stmt.body, self.context)]
        repeat_bound = iter_list.typ.count
        if isinstance(iter_list.typ, DArrayT):
            array_len = get_dyn_array_count(iter_list)
