            if (
                len(ows_tokens) == 4
                and "version" == ows_tokens[0]
                and StrictVersion(ows_tokens[1]) >= StrictVersion("1.0.0")
                and StrictVersion(ows_tokens[1]) <= StrictVersion("3.0.0")
