    if response and response_callback:
        kwargs = {} if not kwargs else kwargs
        kwargs.update(
            {
                "response": response,
                "content": content,
                "status": status,
                "response_headers": response_headers,
                "content_type": content_type,
            }
        )
        return response_callback(**kwargs)
    else:
        if status and status in (301, 302, 303, 307):
            _response = HttpResponse(
                (
                    f"This proxy does not support redirects. The server in '{url}' "
                    f"asked for a redirect to '{response.getheader('Location')}'"
                ),
                status=status,
                content_type=content_type,
            )
            _response["Location"] = response.getheader("Location")
            return fetch_response_headers(_response, response_headers)
        else:
            def _get_message(text):
                _s = text
                if isinstance(text, bytes):
                    _s = text.decode("utf-8", "replace")
                try:
                    found = re.search("<b>Message</b>(.+?)</p>", _s).group(1).strip()
                except Exception:
                    found = _s
                return found
            _response = HttpResponse(
                content=content,
                reason=_get_message(content) if status not in (200, 201) else None,
                status=status,
                content_type=content_type,
            )
            return fetch_response_headers(_response, response_headers)
def check_geoserver_access(request, proxy_path, downstream_path, workspace=None, layername=None, allowed_hosts=[]):
    def strip_prefix(path, prefix):
        if prefix not in path:
            _s_prefix = prefix.split("/", 3)
            _s_path = path.split("/", 3)
            assert _s_prefix[1] == _s_path[1]
            _prefix = f"/{_s_path[1]}/{_s_path[2]}"
        else:
            _prefix = prefix
        assert _prefix in path
        prefix_idx = path.index(_prefix)
        _prefix = path[:prefix_idx] + _prefix
        full_prefix = f"{_prefix}/{layername}/{downstream_path}" if layername else _prefix
        return path[len(full_prefix) :]
    path = strip_prefix(request.get_full_path(), proxy_path)
    raw_url = str("".join([ogc_server_settings.LOCATION, downstream_path, path]))
    if settings.DEFAULT_WORKSPACE or workspace:
        ws = workspace or settings.DEFAULT_WORKSPACE
        if ws and ws in path:
            try:
                path = f'/{strip_prefix(path, f"/{ws}:")}'
            except Exception:
                ws = None
        if proxy_path == f"/gs/{settings.DEFAULT_WORKSPACE}" and layername:
            import posixpath
            raw_url = urljoin(ogc_server_settings.LOCATION, posixpath.join(workspace, layername, downstream_path, path))
        if downstream_path in ("rest/styles") and len(request.body) > 0:
            if ws:
                _url = str("".join([ogc_server_settings.LOCATION, "rest/workspaces/", ws, "/styles", path]))
            else:
                _url = str("".join([ogc_server_settings.LOCATION, "rest/styles", path]))
            raw_url = _url
    if downstream_path in "ows" and ows_endpoint_in_path(path):
        _url = str("".join([ogc_server_settings.LOCATION, "", path[1:]]))
        raw_url = _url
    url = urlsplit(raw_url)
    if f"{ws}/layers" in path:
        downstream_path = "rest/layers"
    elif f"{ws}/styles" in path:
        downstream_path = "rest/styles"
    headers, access_token = get_headers(request, url, unquote(raw_url), allowed_hosts=allowed_hosts)
    return (raw_url, headers, access_token, downstream_path)
@csrf_exempt
def geoserver_proxy(request, proxy_path, downstream_path, workspace=None, layername=None):
    """
    WARNING: Decorators are applied in the order they appear in the source.
    """
    affected_datasets = None
    allowed_hosts = [
        urlsplit(ogc_server_settings.public_url).hostname,
    ]
    raw_url, headers, access_token, downstream_path = check_geoserver_access(
        request, proxy_path, downstream_path, workspace=workspace, layername=layername, allowed_hosts=allowed_hosts
    )
    url = urlsplit(raw_url)
    if re.match(r"^.*(?<!/rest/)/rest/", url.path) and request.method in ("POST", "PUT", "DELETE"):
        if re.match(r"^.*(?<!/rest/)/rest/.*/?styles.*", url.path):
            logger.debug(f"[geoserver_proxy] Updating Style ---> url {url.geturl()}")
            _style_name, _style_ext = os.path.splitext(os.path.basename(urlsplit(url.geturl()).path))
            _parsed_get_args = dict(parse_qsl(urlsplit(url.geturl()).query))
            if _style_name == "styles.json" and request.method == "PUT":
                if _parsed_get_args.get("name"):
                    _style_name, _style_ext = os.path.splitext(_parsed_get_args.get("name"))
            else:
                _style_name, _style_ext = os.path.splitext(_style_name)
            if not style_change_check(request, url.path, style_name=_style_name, access_token=access_token):
                return HttpResponse(
                    _("You don't have permissions to change style for this layer"),
                    content_type="text/plain",
                    status=401,
                )
            if (
                _style_name != "style-check"
                and (_style_ext == ".json" or _parsed_get_args.get("raw"))
                and not re.match(temp_style_name_regex, _style_name)
            ):
                affected_datasets = style_update(request, raw_url, workspace)
        elif re.match(r"^.*(?<!/rest/)/rest/.*/?layers.*", url.path):
            logger.debug(f"[geoserver_proxy] Updating Dataset ---> url {url.geturl()}")
            try:
                _dataset_name = os.path.splitext(os.path.basename(request.path))[0]
                _dataset = Dataset.objects.get(name=_dataset_name)
                affected_datasets = [_dataset]
            except Exception:
                logger.warn(f"Could not find any Dataset {os.path.basename(request.path)} on DB")
    kwargs = {"affected_datasets": affected_datasets}
    raw_url = unquote(raw_url)
    timeout = getattr(ogc_server_settings, "TIMEOUT") or 60
    response = proxy(
        request,
        url=raw_url,
        response_callback=_response_callback,
        timeout=timeout,
        allowed_hosts=allowed_hosts,
        headers=headers,
        access_token=access_token,
        **kwargs,
    )
    return response
logger = logging.getLogger(__name__)
def cascading_delete(dataset_name=None, catalog=None):
    if not dataset_name:
        return
    cat = catalog or gs_catalog
    resource = None
    workspace = None
    try:
        if dataset_name.find(":") != -1 and len(dataset_name.split(":")) == 2:
            workspace, name = dataset_name.split(":")
            ws = cat.get_workspace(workspace)
            store = None
            try:
                store = get_store(cat, name, workspace=ws)
            except FailedRequestError:
                if ogc_server_settings.DATASTORE:
                    try:
                        layers = Dataset.objects.filter(alternate=dataset_name)
                        for layer in layers:
                            store = get_store(cat, layer.store, workspace=ws)
                    except FailedRequestError:
                        logger.debug("the store was not found in geoserver")
                else:
                    logger.debug("the store was not found in geoserver")
            if ws is None or store is None:
                logger.debug("cascading delete was called on a layer where the workspace was not found")
            resource = cat.get_resource(name=name, store=store, workspace=workspace)
        else:
            resource = cat.get_resource(name=dataset_name)
    except OSError as e:
        if e.errno == errno.ECONNREFUSED:
            msg = (
                f'Could not connect to geoserver at "{ogc_server_settings.LOCATION}"'
                f'to save information for layer "{dataset_name}"'
            )
            logger.error(msg)
            return None
        else:
            raise e
    finally:
        cat._cache.clear()
        cat.reset()
        cat.reload()
    if resource is None:
        logger.debug("cascading_delete was called with a non existent resource")
        return
    resource_name = resource.name
    lyr = None
    try:
        lyr = cat.get_layer(resource_name)
    except Exception as e:
        logger.debug(e)
    if lyr is not None:
        store = resource.store
        styles = lyr.styles
        try:
            styles = styles + [lyr.default_style]
        except Exception:
            pass
        if workspace:
            gs_styles = [x for x in cat.get_styles(names=[f"{workspace}_{resource_name}"])]
            styles = styles + gs_styles
        if settings.DEFAULT_WORKSPACE and settings.DEFAULT_WORKSPACE != workspace:
            gs_styles = [x for x in cat.get_styles(names=[f"{settings.DEFAULT_WORKSPACE}_{resource_name}"])]
            styles = styles + gs_styles
        cat.delete(lyr)
        for s in styles:
            if s is not None and s.name not in _default_style_names:
                try:
                    logger.debug(f"Trying to delete Style [{s.name}]")
                    cat.delete(s, purge="true")
                except Exception as e:
                    logger.debug(e)
        try:
            cat.delete(resource, recurse=True)
        except Exception:
            pass
        if (
            store.resource_type == "dataStore"
            and "dbtype" in store.connection_parameters
            and store.connection_parameters["dbtype"] == "postgis"
        ):
            delete_from_postgis(resource_name, store)
        else:
            if store.resource_type == "coverageStore" and store.type != "ImageMosaic":
                try:
                    logger.debug(f" - Going to purge the {store.resource_type} : {store.href}")
                    cat.reset()
                    cat.delete(store, purge="all", recurse=True)
                except Exception as e:
                    logger.debug(e)
            else:
                try:
                    if not store.get_resources():
                        cat.delete(store, recurse=True)
                except Exception as e:
                    logger.debug(e)
def style_update(request, url, workspace=None):
    """
    Sync style stuff from GS to GN.
    Ideally we should call this from a view straight from GXP, and we should use
    gsConfig, that at this time does not support styles updates. Before gsConfig
    is updated, for now we need to parse xml.
    In case of a DELETE, we need to query request.path to get the style name,
    and then remove it.
    In case of a POST or PUT, we need to parse the xml from
    request.body, which is in this format:
    """
    affected_datasets = []
    if request.method in ("POST", "PUT", "DELETE"):
        if "HTTP_USER_AGENT" in request.META:
            if "Trident/7.0" in request.META["HTTP_USER_AGENT"] and "rv:11.0" in request.META["HTTP_USER_AGENT"]:
                txml = re.sub(r'xmlns:NS[0-9]=""', "", request.body)
                txml = re.sub(r"NS[0-9]:", "", txml)
                request._body = txml
        style_name = os.path.basename(request.path)
        sld_title = style_name
        sld_body = None
        sld_url = url
        dataset_name = None
        if "name" in request.GET:
            style_name = request.GET["name"]
            sld_body = request.body
        elif request.method == "DELETE":
            style_name = os.path.basename(request.path)
        else:
            sld_body = request.body
            gs_style = gs_catalog.get_style(name=style_name) or gs_catalog.get_style(
                name=style_name, workspace=workspace
            )
            if gs_style:
                sld_title = gs_style.sld_title if gs_style.style_format != "css" and gs_style.sld_title else style_name
                sld_body = gs_style.sld_body
                sld_url = gs_style.body_href
            else:
                try:
                    tree = ET.ElementTree(dlxml.fromstring(request.body))
                    elm_nameddataset_name = tree.findall(".//{http://www.opengis.net/sld}Name")[0]
                    elm_user_style_name = tree.findall(".//{http://www.opengis.net/sld}Name")[1]
                    elm_user_style_title = tree.find(".//{http://www.opengis.net/sld}Title")
                    dataset_name = elm_nameddataset_name.text
                    if elm_user_style_title is None:
                        sld_title = elm_user_style_name.text
                    else:
                        sld_title = elm_user_style_title.text
                    sld_body = f'<?xml version="1.0" encoding="UTF-8"?>{request.body}'
                except Exception:
                    logger.warn("Could not recognize Style and Dataset name from Request!")
        if request.method == "DELETE":
            if style_name:
                Style.objects.filter(name=style_name).delete()
        if request.method == "POST":
            style = None
            if style_name and not re.match(temp_style_name_regex, style_name):
                style, created = Style.objects.get_or_create(name=style_name)
                style.workspace = workspace
                style.sld_body = sld_body
                style.sld_url = sld_url
                style.sld_title = sld_title
                style.save()
            layer = None
            if dataset_name:
                try:
                    layer = Dataset.objects.get(name=dataset_name)
                except Exception:
                    try:
                        layer = Dataset.objects.get(alternate=dataset_name)
                    except Exception:
                        pass
            if layer:
                if style:
                    style.dataset_styles.add(layer)
                    style.save()
                affected_datasets.append(layer)
        elif request.method == "PUT":
            if style_name and not re.match(temp_style_name_regex, style_name):
                style, created = Style.objects.get_or_create(name=style_name)
                style.workspace = workspace
                style.sld_body = sld_body
                style.sld_url = sld_url
                style.sld_title = sld_title
                style.save()
                for layer in style.dataset_styles.all():
                    affected_datasets.append(layer)
        try:
            if dataset_name:
                _stylefilterparams_geowebcache_dataset(dataset_name)
                _invalidate_geowebcache_dataset(dataset_name)
        except Exception:
            pass
    return affected_datasets
ogc_server_settings = OGC_Servers_Handler(settings.OGC_SERVER)["default"]
def sync_instance_with_geoserver(instance_id, *args, **kwargs):
    """
    Synchronizes the Django Instance with GeoServer layers.
    """
    updatebbox = kwargs.get("updatebbox", True)
    updatemetadata = kwargs.get("updatemetadata", True)
    instance = None
    try:
        instance = Dataset.objects.get(id=instance_id)
    except Dataset.DoesNotExist:
        logger.error(f"Dataset id {instance_id} does not exist yet!")
        raise
    if isinstance(instance, ResourceBase):
        if hasattr(instance, "dataset"):
            instance = instance.dataset
        else:
            return instance
    try:
        instance.set_processing_state("RUNNING")
        if updatemetadata:
            logger.debug(f"... Refresh GeoServer attributes list for Dataset {instance.title}")
            try:
                set_attributes_from_geoserver(instance)
            except Exception as e:
                logger.warning(e)
        _is_remote_instance = hasattr(instance, "subtype") and getattr(instance, "subtype") in ["tileStore", "remote"]
        gs_catalog._cache.clear()
        gs_catalog.reset()
        gs_resource = None
        if not _is_remote_instance:
            values = None
            _tries = 0
            _max_tries = getattr(ogc_server_settings, "MAX_RETRIES", 3)
            if getattr(instance, "overwrite", False):
                base_file, info = instance.get_base_file()
                if base_file:
                    from geonode.geoserver.upload import geoserver_upload
                    gs_name, workspace, values, gs_resource = geoserver_upload(
                        instance,
                        base_file.file.path,
                        instance.owner,
                        instance.name,
                        overwrite=True,
                        title=instance.title,
                        abstract=instance.abstract,
                        charset=instance.charset,
                    )
            values, gs_resource = fetch_gs_resource(instance, values, _tries)
            while not gs_resource and _tries < _max_tries:
                values, gs_resource = fetch_gs_resource(instance, values, _tries)
                _tries += 1
                time.sleep(3)
            metadata_links = []
            for link in instance.link_set.metadata():
                metadata_links.append((link.mime, link.name, link.url))
            if gs_resource:
                logger.debug(f"Found geoserver resource for this dataset: {instance.name}")
                instance.gs_resource = gs_resource
                for key in ["alternate", "store", "subtype"]:
                    setattr(instance, key, get_dataset_storetype(values[key]))
                if updatemetadata:
                    gs_resource.metadata_links = metadata_links
                    if instance.poc:
                        gs_resource.attribution = {
                            "title": str(instance.poc),
                            "width": None,
                            "height": None,
                            "href": None,
                            "url": None,
                            "type": None,
                        }
                        profile = get_user_model().objects.get(username=instance.poc.username)
                        site_url = (
                            settings.SITEURL.rstrip("/") if settings.SITEURL.startswith("http") else settings.SITEURL
                        )
                        gs_resource.attribution_link = site_url + profile.get_absolute_url()
                    try:
                        if settings.RESOURCE_PUBLISHING:
                            if instance.is_published != gs_resource.advertised:
                                gs_resource.advertised = "true"
                        if any(instance.keyword_list()):
                            keywords = gs_resource.keywords + instance.keyword_list()
                            gs_resource.keywords = list(set(keywords))
                        if getattr(ogc_server_settings, "BACKEND_WRITE_ENABLED", True):
                            gs_catalog.save(gs_resource)
                    except Exception as e:
                        msg = f'Error while trying to save resource named {gs_resource} in GeoServer, try to use: "{e}"'
                        e.args = (msg,)
                        logger.warning(e)
                if updatebbox:
                    """Get information from geoserver.
                    The attributes retrieved include:
                    * Bounding Box
                    * SRID
                    """
                    srid = gs_resource.projection
                    bbox = gs_resource.native_bbox
                    ll_bbox = gs_resource.latlon_bbox
                    try:
                        instance.set_bbox_polygon([bbox[0], bbox[2], bbox[1], bbox[3]], srid)
                    except GeoNodeException as e:
                        if not ll_bbox:
                            raise
                        else:
                            logger.exception(e)
                            instance.srid = "EPSG:4326"
                            Dataset.objects.filter(id=instance.id).update(srid=instance.srid)
                    instance.set_ll_bbox_polygon([ll_bbox[0], ll_bbox[2], ll_bbox[1], ll_bbox[3]])
                    if instance.srid:
                        instance.srid_url = (
                            f"http://www.spatialreference.org/ref/{instance.srid.replace(':', '/').lower()}/"
                        )
                    else:
                        raise GeoNodeException(_("Invalid Projection. Dataset is missing CRS!"))
                to_update = {}
                if updatemetadata:
                    to_update = {
                        "title": instance.title or instance.name,
                        "abstract": instance.abstract or "",
                        "alternate": instance.alternate,
                    }
                if updatebbox and is_monochromatic_image(instance.thumbnail_url):
                    to_update["thumbnail_url"] = None
                with transaction.atomic():
                    ResourceBase.objects.filter(id=instance.resourcebase_ptr.id).update(**to_update)
                    to_update["workspace"] = gs_resource.store.workspace.name
                    to_update["store"] = gs_resource.store.name
                    to_update["subtype"] = instance.subtype
                    to_update["typename"] = instance.alternate
                    to_update["srid"] = instance.srid
                    Dataset.objects.filter(id=instance.id).update(**to_update)
                    instance.refresh_from_db()
                if updatemetadata:
                    logger.debug(f"... Refresh Legend links for Dataset {instance.title}")
                    try:
                        set_styles(instance, gs_catalog)
                    except Exception as e:
                        logger.warning(e)
                    try:
                        _stylefilterparams_geowebcache_dataset(instance.alternate)
                        _invalidate_geowebcache_dataset(instance.alternate)
                    except Exception as e:
                        logger.warning(e)
        logger.debug(f"... Creating Default Resource Links for Dataset {instance.title}")
        set_resource_default_links(instance, instance, prune=_is_remote_instance)
        logger.debug(f"... Updating the Catalogue entries for Dataset {instance.title}")
        catalogue_post_save(instance=instance, sender=instance.__class__)
        instance.set_processing_state("PROCESSED")
    except Exception as e:
        logger.exception(e)
        instance.set_processing_state("FAILED")
        raise GeoNodeException(e)
    return instance
def geoserver_upload(
    dataset,
    base_file,
    user,
    name,
    overwrite=True,
    title=None,
    abstract=None,
    permissions=None,
    keywords=(),
    charset="UTF-8",
):
    logger.debug(
        ">>> Step 2. Make sure we are not trying to overwrite a " "existing resource named [%s] with the wrong type",
        name,
    )
    the_dataset_type = geoserver_dataset_type(base_file)
    cat = gs_catalog
    workspace = cat.get_workspace(settings.DEFAULT_WORKSPACE)
    try:
        store = get_store(cat, name, workspace=workspace)
    except geoserver.catalog.FailedRequestError:
        pass
    else:
        resources = cat.get_resources(names=[name], stores=[store], workspaces=[workspace])
        if len(resources) > 0:
            for resource in resources:
                if resource.name == name:
                    msg = "Name already in use and overwrite is False"
                    assert overwrite, msg
                    existing_type = resource.resource_type
                    if existing_type != the_dataset_type:
                        msg = (
                            f"Type of uploaded file {name} ({the_dataset_type}) "
                            "does not match type of existing "
                            f"resource type {existing_type}"
                        )
                        logger.debug(msg)
                        raise GeoNodeException(msg)
    logger.debug(">>> Step 3. Identifying if [%s] is vector or raster and " "gathering extra files", name)
    if the_dataset_type == FeatureType.resource_type:
        logger.debug("Uploading vector layer: [%s]", base_file)
        if ogc_server_settings.DATASTORE:
            create_store_and_resource = _create_db_featurestore
        else:
            create_store_and_resource = _create_featurestore
    elif the_dataset_type == Coverage.resource_type:
        logger.debug("Uploading raster layer: [%s]", base_file)
        create_store_and_resource = _create_coveragestore
    else:
        msg = (
            f"The layer type for name {name} is {the_dataset_type}. It should be "
            f"{FeatureType.resource_type} or {Coverage.resource_type},"
        )
        logger.warn(msg)
        raise GeoNodeException(msg)
    logger.debug(">>> Step 4. Starting upload of [%s] to GeoServer...", name)
    files, _tmpdir = get_files(base_file)
    data = files
    if "shp" not in files:
        data = base_file
    try:
        store, gs_resource = create_store_and_resource(
            name, data, charset=charset, overwrite=overwrite, workspace=workspace
        )
    except UploadError as e:
        msg = f"Could not save the layer {name}, there was an upload " f"error: {e}"
        logger.warn(msg)
        e.args = (msg,)
        raise
    except ConflictingDataError as e:
        msg = (
            f"GeoServer reported a conflict creating a store with name {name}: "
            f'"{e}". This should never happen because a brand new name '
            "should have been generated. But since it happened, "
            "try renaming the file or deleting the store in GeoServer."
        )
        logger.warn(msg)
        e.args = (msg,)
        raise
    except Exception as e:
        logger.error("Error during the creation of the resource in GeoServer", exc_info=e)
        raise e
    logger.debug(f"The File {name} has been sent to GeoServer without errors.")
    logger.debug(f">>> Step 5. Generating the metadata for {name} after successful import to GeoSever")
    if not gs_resource:
        gs_resource = gs_catalog.get_resource(name=name, workspace=workspace)
    if not gs_resource:
        msg = f"GeoNode encountered problems when creating layer {name}.It cannot find the Dataset that matches this Workspace.try renaming your files."
        logger.warn(msg)
        raise GeoNodeException(msg)
    assert gs_resource.name == name
    logger.debug(f">>> Step 6. Making sure [{name}] has a valid projection")
    _native_bbox = None
    try:
        _native_bbox = gs_resource.native_bbox
    except Exception:
        pass
    if _native_bbox and len(_native_bbox) >= 5 and _native_bbox[4:5][0] == "EPSG:4326":
        box = _native_bbox[:4]
        minx, maxx, miny, maxy = [float(a) for a in box]
        if (
            -180 <= round(minx, 5) <= 180
            and -180 <= round(maxx, 5) <= 180
            and -90 <= round(miny, 5) <= 90
            and -90 <= round(maxy, 5) <= 90
        ):
            gs_resource.latlon_bbox = _native_bbox
            gs_resource.projection = "EPSG:4326"
        else:
            logger.warning("BBOX coordinates outside normal EPSG:4326 values for layer " "[%s].", name)
            _native_bbox = [-180, -90, 180, 90, "EPSG:4326"]
            gs_resource.latlon_bbox = _native_bbox
            gs_resource.projection = "EPSG:4326"
            logger.debug("BBOX coordinates forced to [-180, -90, 180, 90] for layer [%s].", name)
    logger.debug(f">>> Step 7. Creating style for [{name}]")
    cat.save(gs_resource)
    publishing = cat.get_layer(name) or gs_resource
    sld = None
    try:
        if "sld" in files:
            with open(files["sld"], "rb") as f:
                sld = f.read()
        else:
            sld = get_sld_for(cat, dataset)
    except Exception as e:
        logger.exception(e)
    style = None
    if sld:
        try:
            style = cat.get_style(name, workspace=workspace)
        except geoserver.catalog.FailedRequestError:
            style = cat.get_style(name)
        try:
            overwrite = style or False
            cat.create_style(name, sld, overwrite=overwrite, raw=True, workspace=workspace)
            cat.reset()
        except geoserver.catalog.ConflictingDataError as e:
            msg = f"There was already a style named {name}_dataset in GeoServer, " f'try to use: "{e}"'
            logger.warn(msg)
            e.args = (msg,)
        except geoserver.catalog.UploadError as e:
            msg = f"Error while trying to upload style named {name}_dataset in GeoServer, " f'try to use: "{e}"'
            e.args = (msg,)
            logger.exception(e)
        if style is None:
            try:
                style = cat.get_style(name, workspace=workspace) or cat.get_style(name)
            except Exception as e:
                style = cat.get_style("point")
                msg = f'Could not find any suitable style in GeoServer for Dataset: "{name}"'
                e.args = (msg,)
                logger.exception(e)
        if style:
            publishing.default_style = style
            logger.debug("default style set to %s", name)
            try:
                cat.save(publishing)
            except geoserver.catalog.FailedRequestError as e:
                msg = f"Error while trying to save resource named {publishing} in GeoServer, " f'try to use: "{e}"'
                e.args = (msg,)
                logger.exception(e)
    logger.debug(">>> Step 8. Creating Django record for [%s]", name)
    alternate = f"{workspace.name}:{gs_resource.name}"
    dataset_uuid = str(uuid.uuid4())
    defaults = dict(
        store=gs_resource.store.name,
        subtype=gs_resource.store.resource_type,
        alternate=alternate,
        title=title or gs_resource.title,
        uuid=dataset_uuid,
        abstract=abstract or gs_resource.abstract or "",
        owner=user,
    )
    return name, workspace.name, defaults, gs_resource
class DatasetDownloadHandler:
    def process_dowload(self, resource=None):
        """
        Generate the response object
        """
        if not resource:
            resource = self.get_resource()
        if not settings.USE_GEOSERVER:
            return HttpResponseRedirect(reverse("download", args=[resource.id]))
        download_format = self.request.GET.get("export_format")
        if download_format and not wps_format_is_supported(download_format, resource.subtype):
            logger.error("The format provided is not valid for the selected resource")
            return JsonResponse({"error": "The format provided is not valid for the selected resource"}, status=500)
        _format = "application/zip" if resource.is_vector() else "image/tiff"
        tpl = get_template("geoserver/dataset_download.xml")
        ctx = {"alternate": resource.alternate, "download_format": download_format or _format}
        payload = tpl.render(ctx)
        client = HttpClient()
        headers = {"Content-type": "application/xml", "Accept": "application/xml"}
        url = f"{settings.OGC_SERVER['default']['LOCATION']}ows?service=WPS&version=1.0.0&REQUEST=Execute"
        if not self.request.user.is_anonymous:
            access_token = get_or_create_token(self.request.user)
            url += f"&access_token={access_token}"
        response, content = client.request(url=url, data=payload, method="post", headers=headers)
        if not response or response.status_code != 200:
            logger.error(f"Download dataset exception: error during call with GeoServer: {content}")
            return JsonResponse(
                {"error": "Download dataset exception: error during call with GeoServer"},
                status=500,
            )
        namespaces = {"ows": "http://www.opengis.net/ows/1.1", "wps": "http://www.opengis.net/wps/1.0.0"}
        response_type = response.headers.get("Content-Type")
        if response_type == "text/xml":
            content = ET.fromstring(response.text)
            exc = content.find("*//ows:Exception", namespaces=namespaces) or content.find(
                "ows:Exception", namespaces=namespaces
            )
            if exc:
                exc_text = exc.find("ows:ExceptionText", namespaces=namespaces)
                logger.error(f"{exc.attrib.get('exceptionCode')} {exc_text.text}")
                return JsonResponse({"error": f"{exc.attrib.get('exceptionCode')}: {exc_text.text}"}, status=500)
        return_response = fetch_response_headers(
            HttpResponse(content=response.content, status=response.status_code, content_type=download_format),
            response.headers,
        )
        return_response.headers["Content-Type"] = download_format or _format
        return return_response

class RepoSync(yum.YumBase):
def localpkgs(directory):
    names = os.listdir(directory)
    cache = {}
    for name in names:
        fn = os.path.join(directory, name)
        try:
            st = os.lstat(fn)
        except os.error:
            continue
        if stat.S_ISDIR(st.st_mode):
            subcache = localpkgs(fn)
            for pkg in subcache.keys():
                cache[pkg] = subcache[pkg]
        elif stat.S_ISREG(st.st_mode) and name.endswith(".rpm"):
            cache[name] = {'path': fn, 'size': st.st_size, 'device': st.st_dev}
    return cache
def parseArgs():
    usage = _("""
    Reposync is used to synchronize a remote yum repository to a local
    directory using yum to retrieve the packages.
    %s [options]
    """) % sys.argv[0]
    parser = OptionParser(usage=usage)
    parser.add_option("-c", "--config", default='/etc/yum.conf',
        help=_('config file to use (defaults to /etc/yum.conf)'))
    parser.add_option("-a", "--arch", default=None,
        help=_('act as if running the specified arch (default: current arch, note: does not override $releasever. x86_64 is a superset for i*86.)'))
    parser.add_option("--source", default=False, dest="source", action="store_true",
                      help=_('operate on source packages'))
    parser.add_option("-r", "--repoid", default=[], action='append',
        help=_("specify repo ids to query, can be specified multiple times (default is all enabled)"))
    parser.add_option("-e", "--cachedir",
        help=_("directory in which to store metadata"))
    parser.add_option("-t", "--tempcache", default=False, action="store_true",
        help=_("Use a temp dir for storing/accessing yum-cache"))
    parser.add_option("-d", "--delete", default=False, action="store_true",
        help=_("delete local packages no longer present in repository"))
    parser.add_option("-p", "--download_path", dest='destdir',
        default=os.getcwd(), help=_("Path to download packages to: defaults to current dir"))
    parser.add_option("--norepopath", dest='norepopath', default=False, action="store_true",
        help=_("Don't add the reponame to the download path. Can only be used when syncing a single repository (default is to add the reponame)"))
    parser.add_option("-g", "--gpgcheck", default=False, action="store_true",
        help=_("Remove packages that fail GPG signature checking after downloading"))
    parser.add_option("-u", "--urls", default=False, action="store_true",
        help=_("Just list urls of what would be downloaded, don't download"))
    parser.add_option("-n", "--newest-only", dest='newest', default=False, action="store_true",
        help=_("Download only newest packages per-repo"))
    parser.add_option("-q", "--quiet", default=False, action="store_true",
        help=_("Output as little as possible"))
    parser.add_option("-l", "--plugins", default=False, action="store_true",
        help=_("enable yum plugin support"))
    parser.add_option("-m", "--downloadcomps", default=False, action="store_true",
        help=_("also download comps.xml"))
    parser.add_option("", "--download-metadata", dest="downloadmd",
        default=False, action="store_true",
        help=_("download all the non-default metadata"))
    (opts, args) = parser.parse_args()
    return (opts, args)
def main():
    (opts, dummy) = parseArgs()
    if not os.path.exists(opts.destdir) and not opts.urls:
        try:
            os.makedirs(opts.destdir)
        except OSError, e:
            print >> sys.stderr, _("Error: Cannot create destination dir %s") % opts.destdir
            sys.exit(1)
    if not os.access(opts.destdir, os.W_OK) and not opts.urls:
        print >> sys.stderr, _("Error: Cannot write to  destination dir %s") % opts.destdir
        sys.exit(1)
    my = RepoSync(opts=opts)
    my.doConfigSetup(fn=opts.config, init_plugins=opts.plugins)
    if os.getuid() != 0 and not opts.cachedir:
        opts.tempcache = True
    if opts.tempcache:
        if not my.setCacheDir(force=True, reuse=False):
            print >> sys.stderr, _("Error: Could not make cachedir, exiting")
            sys.exit(50)
        my.conf.uid = 1
    elif opts.cachedir:
        my.repos.setCacheDir(opts.cachedir)
    if not opts.cachedir:
        try:
            my.doLock()
        except yum.Errors.LockError, e:
            print >> sys.stderr, _("Error: %s") % e
            sys.exit(50)
    if not opts.quiet:
        my.repos.setProgressBar(TextMeter(fo=sys.stdout), TextMultiFileMeter(fo=sys.stdout))
    my.doRepoSetup()
    if len(opts.repoid) > 0:
        myrepos = []
        for glob in opts.repoid:
            add_repos = my.repos.findRepos(glob)
            if not add_repos:
                print >> sys.stderr, _("Warning: cannot find repository %s") % glob
                continue
            myrepos.extend(add_repos)
        if not myrepos:
            print >> sys.stderr, _("No repositories found")
            sys.exit(1)
        for repo in my.repos.repos.values():
            repo.disable()
        for repo in myrepos:
            repo.enable()
    if len(my.repos.listEnabled()) > 1 and opts.norepopath:
        print >> sys.stderr, _("Error: Can't use --norepopath with multiple repositories")
        sys.exit(1)
    try:
        arches = rpmUtils.arch.getArchList(opts.arch)
        if opts.source:
            arches += ['src']
        my.doSackSetup(arches)
    except yum.Errors.RepoError, e:
        print >> sys.stderr, _("Error setting up repositories: %s") % e
        sys.exit(1)
    exit_code = 0
    for repo in my.repos.listEnabled():
        reposack = ListPackageSack(my.pkgSack.returnPackages(repoid=repo.id))
        if opts.newest:
            download_list = reposack.returnNewestByNameArch()
        else:
            download_list = list(reposack)
        if opts.norepopath:
            local_repo_path = opts.destdir
        else:
            local_repo_path = opts.destdir + '/' + repo.id
        if opts.delete and os.path.exists(local_repo_path):
            current_pkgs = localpkgs(local_repo_path)
            download_set = {}
            for pkg in download_list:
                rpmname = os.path.basename(pkg.remote_path)
                download_set[rpmname] = 1
            for pkg in current_pkgs:
                if pkg in download_set:
                    continue
                if not opts.quiet:
                    my.logger.info("Removing obsolete %s", pkg)
                os.unlink(current_pkgs[pkg]['path'])
        if opts.downloadcomps or opts.downloadmd:
            if not os.path.exists(local_repo_path):
                try:
                    os.makedirs(local_repo_path)
                except IOError, e:
                    my.logger.error("Could not make repo subdir: %s" % e)
                    my.closeRpmDB()
                    sys.exit(1)
            if opts.downloadcomps:
                wanted_types = ['group']
            if opts.downloadmd:
                wanted_types = repo.repoXML.fileTypes()
            for ftype in repo.repoXML.fileTypes():
                if ftype in ['primary', 'primary_db', 'filelists',
                             'filelists_db', 'other', 'other_db']:
                    continue
                if ftype not in wanted_types:
                    continue
                try:
                    resultfile = repo.retrieveMD(ftype)
                    basename = os.path.basename(resultfile)
                    if ftype == 'group' and opts.downloadcomps:
                        basename = 'comps.xml'
                    shutil.copyfile(resultfile, "%s/%s" % (local_repo_path, basename))
                except yum.Errors.RepoMDError, e:
                    if not opts.quiet:
                        my.logger.error("Unable to fetch metadata: %s" % e)
        remote_size = 0
        if not opts.urls:
            for pkg in download_list:
                local = os.path.join(local_repo_path, pkg.remote_path)
                sz = int(pkg.returnSimple('packagesize'))
                if os.path.exists(local) and os.path.getsize(local) == sz:
                    continue
                remote_size += sz
        if hasattr(urlgrabber.progress, 'text_meter_total_size'):
            urlgrabber.progress.text_meter_total_size(remote_size)
        download_list.sort(key=lambda pkg: pkg.name)
        if opts.urls:
            for pkg in download_list:
                local = os.path.join(local_repo_path, pkg.remote_path)
                if not (os.path.exists(local) and my.verifyPkg(local, pkg, False)):
                    print urljoin(pkg.repo.urls[0], pkg.remote_path)
            continue
        if not os.path.exists(local_repo_path):
            os.makedirs(local_repo_path)
        for pkg in download_list:
            pkg.localpath = os.path.join(local_repo_path, pkg.remote_path)
            pkg.repo.copy_local = True
            pkg.repo.cache = 0
            localdir = os.path.dirname(pkg.localpath)
            if not os.path.exists(localdir):
                os.makedirs(localdir)
        probs = my.downloadPkgs(download_list)
        if probs:
            exit_code = 1
            for key in probs:
                for error in probs[key]:
                    my.logger.error('%s: %s', key, error)
        if opts.gpgcheck:
            for pkg in download_list:
                result, error = my.sigCheckPkg(pkg)
                if result != 0:
                    rpmfn = os.path.basename(pkg.remote_path)
                    if result == 1:
                        my.logger.warning('Removing %s, due to missing GPG key.' % rpmfn)
                    elif result == 2:
                        my.logger.warning('Removing %s due to failed signature check.' % rpmfn)
                    else:
                        my.logger.warning('Removing %s due to failed signature check: %s' % rpmfn)
                    os.unlink(pkg.localpath)
                    exit_code = 1
                    continue
    my.closeRpmDB()
    sys.exit(exit_code)
if __name__ == "__main__":
    main()

