                                headers.pop(hdrs.CONTENT_LENGTH)
                        r_url = resp.headers.get(hdrs.LOCATION) or resp.headers.get(
                            hdrs.URI
                        )
                        if r_url is None:
                            break
                        else:
                            resp.release()
