    args_ir,
    context,
    value=None,
    gas=None,
    skip_contract_check=None,
    expr=None,
):
    if value is None:
        value = 0
    if gas is None:
        gas = "gas"
    if skip_contract_check is None:
        skip_contract_check = False
    assert len(contract_sig.base_args) <= len(args_ir) <= len(contract_sig.args)
    if context.is_constant() and contract_sig.mutability not in ("view", "pure"):
        raise StateAccessViolation(
            f"May not call state modifying function '{contract_sig.name}' "
            f"within {context.pp_constancy()}.",
            expr,
        )
    sub = ["seq"]
    buf, arg_packer, args_ofst, args_len = _pack_arguments(contract_sig, args_ir, context)
    ret_unpacker, ret_ofst, ret_len = _unpack_returndata(
        buf, contract_sig, skip_contract_check, context
    )
    sub += arg_packer
    if contract_sig.return_type is None and not skip_contract_check:
        sub.append(["assert", ["extcodesize", contract_address]])
    if context.is_constant() or contract_sig.mutability in ("view", "pure"):
        call_op = ["staticcall", gas, contract_address, args_ofst, args_len, ret_ofst, ret_len]
    else:
        call_op = ["call", gas, contract_address, value, args_ofst, args_len, ret_ofst, ret_len]
    sub.append(check_external_call(call_op))
    if contract_sig.return_type is not None:
        sub += ret_unpacker
    ret = IRnode.from_list(
        sub,
        typ=contract_sig.return_type,
        location=MEMORY,
        encoding=_returndata_encoding(contract_sig),
    )
    return ret
def make_return_stmt(ir_val: IRnode, stmt: Any, context: Context) -> Optional[IRnode]:
    sig = context.sig
    jump_to_exit = ["exit_to", f"_sym_{sig.exit_sequence_label}"]
    if context.return_type is None:
        if stmt.value is not None:
            return None
    else:
        check_assign(dummy_node_for_type(context.return_type), ir_val)
    def finalize(fill_return_buffer):
        fill_return_buffer = IRnode.from_list(
            fill_return_buffer, annotation=f"fill return buffer {sig._ir_identifier}"
        )
        cleanup_loops = "cleanup_repeat" if context.forvars else "pass"
        return IRnode.from_list(["seq", fill_return_buffer, cleanup_loops, jump_to_exit])
    if context.return_type is None:
        jump_to_exit += ["return_pc"]
        return finalize(["pass"])
    if context.is_internal:
        dst = IRnode.from_list(["return_buffer"], typ=context.return_type, location=MEMORY)
        fill_return_buffer = make_setter(dst, ir_val)
        jump_to_exit += ["return_pc"]
        return finalize(fill_return_buffer)
    else:
        external_return_type = calculate_type_for_external_return(context.return_type)
        maxlen = external_return_type.abi_type.size_bound()
        can_skip_encode = (
            abi_encoding_matches_vyper(ir_val.typ)
            and ir_val.location == MEMORY
            and not needs_clamp(ir_val.typ, ir_val.encoding)
        )
        if can_skip_encode:
            assert ir_val.typ.memory_bytes_required == maxlen
            jump_to_exit += [ir_val, maxlen]
            return finalize(["pass"])
        ir_val = wrap_value_for_external_return(ir_val)
        return_buffer_ofst = context.new_internal_variable(get_type_for_exact_size(maxlen))
        return_len = abi_encode(return_buffer_ofst, ir_val, context, returns_len=True, bufsz=maxlen)
        jump_to_exit += [return_buffer_ofst, return_len]
        return finalize(["pass"])
def ir_for_self_call(stmt_expr, context):
    from vyper.codegen.expr import Expr
    method_name = stmt_expr.func.attr
    pos_args_ir = [Expr(x, context).ir_node for x in stmt_expr.args]
    sig, kw_vals = context.lookup_internal_function(method_name, pos_args_ir)
    kw_args_ir = [Expr(x, context).ir_node for x in kw_vals]
    args_ir = pos_args_ir + kw_args_ir
    args_tuple_t = TupleType([x.typ for x in args_ir])
    args_as_tuple = IRnode.from_list(["multi"] + [x for x in args_ir], typ=args_tuple_t)
    context.register_callee(sig.frame_size)
    if context.is_constant() and sig.mutability not in ("view", "pure"):
        raise StateAccessViolation(
            f"May not call state modifying function "
            f"'{method_name}' within {context.pp_constancy()}.",
            stmt_expr,
        )
    if not sig.internal:
        raise StructureException("Cannot call external functions via 'self'", stmt_expr)
    return_label = _generate_label(f"{sig.internal_function_label}_call")
    if sig.return_type is not None:
        return_buffer = IRnode.from_list(
            context.new_internal_variable(sig.return_type), annotation=f"{return_label}_return_buf"
        )
    else:
        return_buffer = None
    dst_tuple_t = TupleType([arg.typ for arg in sig.args])
    args_dst = IRnode(sig.frame_start, typ=dst_tuple_t, location=MEMORY)
    if args_as_tuple.contains_self_call:
        copy_args = ["seq"]
        tmp_args_buf = IRnode(
            context.new_internal_variable(dst_tuple_t),
            typ=dst_tuple_t,
            location=MEMORY,
        )
        copy_args.append(
            make_setter(tmp_args_buf, args_as_tuple)
        )
        copy_args.append(make_setter(args_dst, tmp_args_buf))
    else:
        copy_args = make_setter(args_dst, args_as_tuple)
    goto_op = ["goto", sig.internal_function_label]
    if return_buffer is not None:
        goto_op += [return_buffer]
    goto_op += [push_label_to_stack(return_label)]
    call_sequence = [
        "seq",
        copy_args,
        goto_op,
        ["label", return_label, ["var_list"], "pass"],
    ]
    if return_buffer is not None:
        call_sequence += [return_buffer]
    o = IRnode.from_list(
        call_sequence,
        typ=sig.return_type,
        location=MEMORY,
        annotation=stmt_expr.get("node_source_code"),
        add_gas_estimate=sig.gas,
    )
    o.is_self_call = True
    return o
class Compare(VyperNode):
    def evaluate(self) -> VyperNode:
        """
        Attempt to evaluate the comparison.
        Returns
        -------
        NameConstant
            Node representing the result of the evaluation.
        """
        left, right = self.left, self.right
        if not isinstance(left, Constant):
            raise UnfoldableNode("Node contains invalid field(s) for evaluation")
        if isinstance(self.op, (In, NotIn)):
            if not isinstance(right, List):
                raise UnfoldableNode("Node contains invalid field(s) for evaluation")
            if next((i for i in right.elements if not isinstance(i, Constant)), None):
                raise UnfoldableNode("Node contains invalid field(s) for evaluation")
            if len(set([type(i) for i in right.elements])) > 1:
                raise UnfoldableNode("List contains multiple literal types")
            value = self.op._op(left.value, [i.value for i in right.elements])
            return NameConstant.from_node(self, value=value)
        if not isinstance(left, type(right)):
            raise UnfoldableNode("Cannot compare different literal types")
        if not isinstance(self.op, (Eq, NotEq)) and not isinstance(left, (Int, Decimal)):
            raise TypeMismatch(f"Invalid literal types for {self.op.description} comparison", self)
        value = self.op._op(left.value, right.value)
        return NameConstant.from_node(self, value=value)
class FunctionNodeVisitor(VyperNodeVisitorBase):
    def visit_For(self, node):
        if isinstance(node.iter, vy_ast.Subscript):
            raise StructureException("Cannot iterate over a nested list", node.iter)
        if isinstance(node.iter, vy_ast.Call):
            if node.iter.get("func.id") != "range":
                raise IteratorException(
                    "Cannot iterate over the result of a function call", node.iter
                )
            validate_call_args(node.iter, (1, 2))
            args = node.iter.args
            if len(args) == 1:
                if not isinstance(args[0], vy_ast.Num):
                    raise StateAccessViolation("Value must be a literal", node)
                if args[0].value <= 0:
                    raise StructureException("For loop must have at least 1 iteration", args[0])
                validate_expected_type(args[0], IntegerAbstractType())
                type_list = get_possible_types_from_node(args[0])
            else:
                validate_expected_type(args[0], IntegerAbstractType())
                type_list = get_common_types(*args)
                if not isinstance(args[0], vy_ast.Constant):
                    if not isinstance(args[1], vy_ast.BinOp) or not isinstance(
                        args[1].op, vy_ast.Add
                    ):
                        raise StructureException(
                            "Second element must be the first element plus a literal value",
                            args[0],
                        )
                    if not vy_ast.compare_nodes(args[0], args[1].left):
                        raise StructureException(
                            "First and second variable must be the same", args[1].left
                        )
                    if not isinstance(args[1].right, vy_ast.Int):
                        raise InvalidLiteral("Literal must be an integer", args[1].right)
                    if args[1].right.value < 1:
                        raise StructureException(
                            f"For loop has invalid number of iterations ({args[1].right.value}),"
                            " the value must be greater than zero",
                            args[1].right,
                        )
                else:
                    if not isinstance(args[1], vy_ast.Int):
                        raise InvalidType("Value must be a literal integer", args[1])
                    validate_expected_type(args[1], IntegerAbstractType())
                    if args[0].value >= args[1].value:
                        raise StructureException("Second value must be > first value", args[1])
        else:
            type_list = [
                i.value_type
                for i in get_possible_types_from_node(node.iter)
                if isinstance(i, (DynamicArrayDefinition, ArrayDefinition))
            ]
        if not type_list:
            raise InvalidType("Not an iterable type", node.iter)
        if isinstance(node.iter, (vy_ast.Name, vy_ast.Attribute)):
            assign = _check_iterator_assign(node.iter, node)
            if assign:
                raise ImmutableViolation("Cannot modify array during iteration", assign)
        if node.iter.get("value.id") == "self":
            iter_name = node.iter.attr
            for call_node in node.get_descendants(vy_ast.Call, {"func.value.id": "self"}):
                fn_name = call_node.func.attr
                fn_node = self.vyper_module.get_children(vy_ast.FunctionDef, {"name": fn_name})[0]
                if _check_iterator_assign(node.iter, fn_node):
                    raise ImmutableViolation(
                        f"Cannot call '{fn_name}' inside for loop, it potentially "
                        f"modifies iterated storage variable '{iter_name}'",
                        call_node,
                    )
                for name in self.namespace["self"].members[fn_name].recursive_calls:
                    fn_node = self.vyper_module.get_children(vy_ast.FunctionDef, {"name": name})[0]
                    if _check_iterator_assign(node.iter, fn_node):
                        raise ImmutableViolation(
                            f"Cannot call '{fn_name}' inside for loop, it may call to '{name}' "
                            f"which potentially modifies iterated storage variable '{iter_name}'",
                            call_node,
                        )
        self.expr_visitor.visit(node.iter)
        for_loop_exceptions = []
        iter_name = node.target.id
        for type_ in type_list:
            type_ = copy.deepcopy(type_)
            type_.is_constant = True
            with self.namespace.enter_scope():
                try:
                    self.namespace[iter_name] = type_
                except VyperException as exc:
                    raise exc.with_annotation(node) from None
                try:
                    for n in node.body:
                        self.visit(n)
                    node.target._metadata["type"] = type_
                    return
                except (TypeMismatch, InvalidOperation) as exc:
                    for_loop_exceptions.append(exc)
        if len(set(str(i) for i in for_loop_exceptions)) == 1:
            raise for_loop_exceptions[0]
        types_str = [str(i) for i in type_list]
        given_str = f"{', '.join(types_str[:1])} or {types_str[-1]}"
        raise TypeMismatch(
            f"Iterator value '{iter_name}' may be cast as {given_str}, "
            "but type checking fails with all possible types:",
            node,
            *(
                (f"Casting '{iter_name}' as {type_}: {exc.message}", exc.annotations[0])
                for type_, exc in zip(type_list, for_loop_exceptions)
            ),
        )
def checksum_encode(addr):
    assert addr[:2] == "0x" and len(addr) == 42, addr
    o = ""
    v = bytes_to_int(keccak256(addr[2:].lower().encode("utf-8")))
    for i, c in enumerate(addr[2:]):
        if c in "0123456789":
            o += c
        else:
            o += c.upper() if (v & (2 ** (255 - 4 * i))) else c.lower()
    return "0x" + o
def _encode_log_topics(expr, event_id, arg_nodes, context):
            value = keccak256_helper(expr, arg, context=context)
def ir_node_for_log(expr, event, topic_nodes, data_nodes, context):
    """Taking IR nodes as arguments, create the IR node for a Log statement.
    Arguments:
      expr: The original Log expression
      buf: A pre-allocated buffer for the output
      _maxlen: The length of the buffer, for sanity checking
      event: The Event type
      topic_nodes: list of IRnodes which calculate the event topics
      data_nodes: list of IRnodes which calculate the event data
      context: current memory/frame context
    """
    topics = _encode_log_topics(expr, event.event_id, topic_nodes, context)
    data = ir_tuple_from_args(data_nodes)
    bufsz = data.typ.abi_type.size_bound()
    buf = context.new_internal_variable(get_type_for_exact_size(bufsz))
    encode_data = abi_encode(buf, data, context, returns_len=True, bufsz=bufsz)
    assert len(topics) <= 4, "too many topics"
    log_opcode = "log" + str(len(topics))
    return IRnode.from_list(
        [log_opcode, buf, encode_data] + topics,
        add_gas_estimate=_gas_bound(len(topics), bufsz),
        annotation=f"LOG event {event.signature}",
    )
def _check_bytes(expr, arg, output_type, max_bytes_allowed):
    if isinstance(arg.typ, ByteArrayLike):
        if arg.typ.maxlen > max_bytes_allowed:
            _FAIL(arg.typ, output_type, expr)
    else:
        assert output_type.memory_bytes_required == 32
@_input_types("int", "bytes_m", "decimal", "bytes", "address", "bool")
def to_int(expr, arg, out_typ):
    int_info = out_typ._int_info
    assert int_info.bits % 8 == 0
    _check_bytes(expr, arg, out_typ, 32)
    if isinstance(expr, vy_ast.Constant):
        return _literal_int(expr, out_typ)
    elif isinstance(arg.typ, ByteArrayType):
        arg_typ = arg.typ
        arg = _bytes_to_num(arg, out_typ, signed=int_info.is_signed)
        if arg_typ.maxlen * 8 > int_info.bits:
            arg = int_clamp(arg, int_info.bits, signed=int_info.is_signed)
    elif is_bytes_m_type(arg.typ):
        arg_info = arg.typ._bytes_info
        arg = _bytes_to_num(arg, out_typ, signed=int_info.is_signed)
        if arg_info.m_bits > int_info.bits:
            arg = int_clamp(arg, int_info.bits, signed=int_info.is_signed)
    elif is_decimal_type(arg.typ):
        arg_info = arg.typ._decimal_info
        arg = _fixed_to_int(arg, out_typ)
        arg = _num_clamp(arg, int_info, arg_info)
    elif is_integer_type(arg.typ):
        arg_info = arg.typ._int_info
        arg = _num_clamp(arg, int_info, arg_info)
    elif is_base_type(arg.typ, "address"):
        if int_info.is_signed:
            _FAIL(arg.typ, out_typ, expr)
        if int_info.bits > 160:
            arg = int_clamp(arg, 160, signed=False)
    return IRnode.from_list(arg, typ=out_typ)
MEMORY = AddrSpace("memory", 32, "mload", "mstore")

class Expr:
    def parse_Hex(self):
        hexstr = self.expr.value
            assert checksum_encode(hexstr) == hexstr
            n_bytes = (len(hexstr) - 2) // 2
            val = int(hexstr, 16) << 8 * (32 - n_bytes)
    def _make_bytelike(self, btype, bytez, bytez_length):
        placeholder = self.context.new_internal_variable(btype)
        seq = []
        seq.append(["mstore", placeholder, bytez_length])
        for i in range(0, len(bytez), 32):
            seq.append(
                [
                    "mstore",
                    ["add", placeholder, i + 32],
                    bytes_to_int((bytez + b"\x00" * 31)[i : i + 32]),
                ]
            )
        return IRnode.from_list(
            ["seq"] + seq + [placeholder],
            typ=btype,
            location=MEMORY,
            annotation=f"Create {btype}: {bytez}",
        )
    def parse_Attribute(self):
        if self.expr.attr == "balance":
            addr = Expr.parse_value_expr(self.expr.value, self.context)
            if is_base_type(addr.typ, "address"):
                if (
                    isinstance(self.expr.value, vy_ast.Name)
                    and self.expr.value.id == "self"
                    and version_check(begin="istanbul")
                ):
                    seq = ["selfbalance"]
                else:
                    seq = ["balance", addr]
                return IRnode.from_list(seq, typ=BaseType("uint256"))
        elif self.expr.attr == "codesize" or self.expr.attr == "is_contract":
            addr = Expr.parse_value_expr(self.expr.value, self.context)
            if is_base_type(addr.typ, "address"):
                if self.expr.attr == "codesize":
                    if self.expr.value.id == "self":
                        eval_code = ["codesize"]
                    else:
                        eval_code = ["extcodesize", addr]
                    output_type = "uint256"
                else:
                    eval_code = ["gt", ["extcodesize", addr], 0]
                    output_type = "bool"
                return IRnode.from_list(eval_code, typ=BaseType(output_type))
        elif self.expr.attr == "codehash":
            addr = Expr.parse_value_expr(self.expr.value, self.context)
